  "initiative": { pl: "inicjatywa", en: "initiative", enAlt: ["betting initiative","betting lead"], def: "Rola ostatniego agresora: to on zwykle wykonuje następny zakład.", area: "board", forms: ["inicjatywa","inicjatywy","inicjatywę","inicjatywą","inicjatywie"] },
  "range-advantage": { pl: "przewaga zakresu", en: "range advantage", enAlt: [], def: "Sytuacja, w której zakres jednego gracza ma na danym stole łącznie większe equity niż zakres rywala.", area: "strategy", forms: ["przewaga zakresu","przewagi zakresu","przewagę zakresu","przewagą zakresu","przewadze zakresu"] },
  "nuts-advantage": { pl: "przewaga nutsów", en: "nuts advantage", enAlt: [], def: "Sytuacja, w której jeden gracz ma w zakresie proporcjonalnie więcej najsilniejszych rąk niż rywal.", area: "strategy", forms: ["przewaga nutsów","przewagi nutsów","przewagę nutsów","przewagą nutsów","przewadze nutsów"] },
  "nuts": { pl: "nuts", en: "nuts", enAlt: [], def: "Najsilniejsza możliwa ręka na danym stole w danej chwili. Przykład: na stole K♥ 9♥ 4♥ 2♣ jest nią kolor z asem kier.", area: "strategy" },
  "polarized": { pl: "spolaryzowany", en: "polarized", enAlt: [], def: "O zakresie: złożony głównie z bardzo silnych rąk i z blefów, prawie bez rąk średnich.", area: "strategy", forms: ["spolaryzowany","spolaryzowana","spolaryzowane","spolaryzowanego","spolaryzowanym","spolaryzowanych","spolaryzowanej","spolaryzowaną"] },
