  "linear": { pl: "liniowy", en: "linear", enAlt: [], def: "O zakresie: zbudowany od góry, z najsilniejszych rąk w dół, bez osobnej grupy blefów. W polskich tekstach spotyka się pokrewne „merged range” (zakres niespolaryzowany); według opublikowanych analiz solvera merged to kształt pośredni między tym zakresem a spolaryzowanym.", area: "strategy", forms: ["liniowy","liniowa","liniowe","liniowego","liniowym","liniowych","liniowej","liniową"] },
  "condensed": { pl: "skondensowany", en: "condensed", enAlt: ["depolarized"], def: "O zakresie: bez najsilniejszych rąk (ograniczony od góry) i złożony głównie ze średnich rąk; przeciwieństwo spolaryzowanego.", area: "strategy", forms: ["skondensowany","skondensowana","skondensowane","skondensowanego","skondensowanym","skondensowanych"] },
  "value": { pl: "wartość", en: "value", enAlt: [], def: "Zakładanie z silną ręką po to, żeby rywal sprawdził zakład słabszą ręką.", area: "strategy", forms: ["dla wartości","za wartość","ulice wartości","ulic wartości","ulica wartości","ulicę wartości"] },
  "value-bet": { pl: "value bet", en: "value bet", enAlt: [], def: "Pojedynczy zakład dla wartości: stawiany silną ręką po to, żeby sprawdziły go słabsze ręce.", area: "strategy" },
  "bluff": { pl: "blef", en: "bluff", enAlt: [], def: "Zakład ze słabą ręką, która raczej nie wygra na showdownie, żeby rywal spasował lepszą rękę.", area: "strategy", forms: ["blef","blefu","blefem","blefie","blefy","blefów","blefami","blefach","blefom","blefuje","blefujesz","blefuję","blefują","blefować","blefował","blefowałeś","blefując","blefuj","blefowania","blefowanie","blefowaniu"] },
  "semi-bluff": { pl: "semi-blef", en: "semi-bluff", enAlt: [], def: "Zakład z ręką jeszcze słabą, ale z szansą na poprawę (np. z drawem): wygrywasz, gdy rywal spasuje albo gdy trafisz.", area: "strategy", forms: ["semi-blef","semi-blefu","semi-blefem","semi-blefy","semi-blefów","semi-blefami","semi-blefach","semi-blefie"] },
  "blocker": { pl: "bloker", en: "blocker", enAlt: [], def: "Karta w Twojej ręce, która zmniejsza szansę, że rywal ma określone ręce. Przykład: z asem kier rywal nie może mieć koloru z asem kier.", area: "strategy", forms: ["bloker","blokera","blokerem","blokery","blokerów","blokerami","blokerach","blokerze"] },
  "bluff-catcher": { pl: "bluff-catcher", en: "bluff catcher", enAlt: [], def: "Ręka, która pokonuje tylko blefy rywala, a przegrywa z jego zakładami dla wartości.", area: "strategy" },
