  "second-barrel": { pl: "second barrel", en: "second barrel", enAlt: ["double barrel"], def: "Drugi zakład z rzędu: po c-becie na flopie gracz stawia znowu na turnie.", area: "strategy" },
  "probe-bet": { pl: "probe", en: "probe bet", enAlt: [], def: "Zakład na turnie gracza bez pozycji po tym, jak agresor preflop zaczekał na flopie zamiast zrobić c-bet.", area: "strategy" },
  "donk-bet": { pl: "donk bet", en: "donk bet", enAlt: [], def: "Zakład gracza, który stawia, zanim agresor z poprzedniej rundy zdążył zagrać.", area: "strategy" },
