export type TermKey = keyof typeof TERMS;

/** Definicje w językach innych niż polski (D-335): content/<język>/terms-def.yaml, klucz terminu → definicja. */
export const TERM_DEFS: Readonly<Partial<Record<string, Readonly<Record<string, string>>>>> = {
  "en": {"royal-flush":"The highest hand in poker: ace, king, queen, jack and ten of the same suit, e.g. A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Five consecutive cards of the same suit, e.g. 5♥ 6♥ 7♥ 8♥ 9♥. The highest version (ace down to ten) has its own name and is the strongest hand in the game.","four-of-a-kind":"Four cards of the same rank, e.g. four sevens. If two players have four of a kind of the same rank, the higher fifth card (the kicker) wins.","full-house":"Three of a kind plus a pair in one hand, e.g. three queens and two fives. Between two full houses, the higher three of a kind wins.","flush":"Five cards of the same suit (♠, ♥, ♦ or ♣) that are not in sequence. Between two such hands, the one with the higher top card wins; if those are equal, the next card decides.","straight":"Five consecutive cards, not all of the same suit, e.g. 5-6-7-8-9. The ace can be the highest card (A-K-Q-J-T) or the lowest (A-2-3-4-5).","three-of-a-kind":"Three cards of the same rank and two other cards. In hold'em it has two versions with their own names: a set, when the pair is in your hand and the third card is on the board, and trips, when the pair is on the board and the third card is in your hand.","set":"Three of a kind made from a pair in your hand and one card on the board, e.g. 7♣ 7♦ on a K-7-2 flop.","two-pair":"Two different pairs and a fifth card, e.g. K-K-8-8-3. Ties are decided first by the higher pair, then the lower pair, and finally the fifth card.","pair":"Two cards of the same rank and three other cards, e.g. two nines. Only high card is weaker.","high-card":"A hand with no pair or better combination; its strength is set by the highest card, and on a tie by the next ones.","kicker":"The highest card outside the made hand, used to break a tie. Example: a pair of aces with a king beats a pair of aces with a queen.","wheel":"The lowest straight: A-2-3-4-5, where the ace counts as the lowest card.","check":"Continuing without putting in chips, possible only when you don't have to add anything: nobody has bet yet in this betting round (before the flop, the big blind can do this when nobody has raised). Not to be confused with call, which means adding chips to match an opponent's bet.","bet":"The first chips put in during a betting round in which nobody has bet yet (in a broader sense, any chips put into the pot are called a bet).","call":"Putting into the pot the amount of an opponent's bet or raise so you can keep playing. Not to be confused with check, which means continuing without betting when nobody has bet.","raise":"Increasing the amount above an opponent's bet; the other players must add the difference, raise again or fold.","fold":"Giving up the hand: you throw away your cards and lose whatever you have already put into the pot.","check-raise":"You check first, and when an opponent bets, you raise them in the same betting round.","all-in":"Betting all of your chips. From each opponent you can then win at most as much as you put in yourself; the rest is played for in a side pot.","pot":"All the chips bet in the current hand. They go to the player with the best hand at showdown (with side pots, each pot is decided separately) or to the player left when everyone else folds.","side-pot":"A separate pot created when someone is all-in: only players who put in more than the all-in player compete for it, so the all-in player cannot win it.","split-pot":"A situation where players with equal hands share the pot, e.g. when both are playing the same straight on the board.","playing-the-board":"A situation where your best five-card hand is made only of community cards; your hole cards add nothing, so at best you split the pot.","board":"The face-up community cards in the middle (flop, turn, river) that all players use. It means the cards, not the table you play at.","community-cards":"Cards dealt face up in the middle that every player can use to make a hand; in hold'em there are five.","hole-cards":"The two face-down cards you get at the start of a hand in hold'em; only you can see them.","small-blind":"The smaller forced bet posted before the deal by the player to the left of the button (heads up, by the button itself); the seat is also called this.","big-blind":"The larger forced bet posted before the deal by the second player to the left of the button (heads up, by the player opposite the button); the seat is also called this. It is also used as the unit for stack sizes and results.","chips":"The discs used to play at the table; in cash games they represent money, in tournaments tournament points.","stack":"All the chips a player has in front of them; usually given in big blinds (e.g. 100 big blinds).","street":"A slang name for a betting round: preflop, flop, turn and river are the four streets. Example: “value on three streets” means value bets on the flop, turn and river.","betting-round":"A stage of the hand in which players take turns to check, bet, call, raise or fold; in hold'em there are four: preflop, flop, turn and river.","preflop":"The first betting round: after the hole cards are dealt, before the flop comes.","flop":"The first three community cards, dealt together after preflop betting; the second betting round is also called this.","turn":"The fourth community card and the third betting round.","river":"The fifth and last community card, and the last betting round before showdown.","showdown":"Revealing the cards after the last betting round when at least two players are still in the hand; the best hand takes the pot.","position":"Your seat at the table relative to the button, which sets the order of action. Whoever acts later sees more of the opponents' actions before deciding.","in-position":"The situation of a player who acts last after the flop, so they see the opponent's action before deciding.","out-of-position":"The situation of a player who acts before the opponent after the flop, so they decide without knowing the opponent's action.","early-position":"The first seats to act before the flop (e.g. UTG); many players are still to act after you.","late-position":"The seats that act last: the button and the seats just before it, especially the cutoff.","utg":"The first player to act before the flop, sitting directly to the left of the big blind.","hijack":"The seat directly before the cutoff, i.e. the second seat to the right of the button.","cutoff":"The seat directly to the right of the button, acting just before it.","button":"The dealer's seat, marked with a “dealer” disc. After the flop it acts last in every betting round.","outs":"A card still in the deck that will improve your hand, usually by completing a draw. Example: with a flush draw, your outs are the remaining cards of your suit.","draw":"A hand that is not yet a strong made hand but can become one with the next community cards, e.g. when you are one card short of a flush or a straight.","flush-draw":"Four cards of the same suit (in your hand and on the board together); you need one more to make a flush.","straight-draw":"Four cards that need one more to make a straight. Types: OESD (a card is missing at either of two ends) and gutshot (a card is missing in the middle).","oesd":"OESD is short for open-ended straight draw: a straight draw of four consecutive cards completed by a card at either end, e.g. 5-6-7-8 needs a four or a nine.","gutshot":"A straight draw missing one specific rank in the middle, e.g. 5-6-8-9 needs only a seven.","backdoor":"A draw on the flop that needs two matching cards in a row, on the turn and on the river, e.g. three cards of one suit after the flop.","pot-odds":"The ratio of the amount you have to put in to the pot you can win (including the opponent's bet). It tells you how often you need to win for a call to be profitable.","implied-odds":"Pot odds increased by the chips you expect to win on later streets if you hit your hand.","equity":"Your chance of winning the pot if all remaining cards were dealt with no more betting; usually given as a percentage.","equity-realization":"How much of its equity a hand turns into winnings when betting continues (it can realize less or more than its equity); it depends on things like position and how easy the hand is to play.","expected-value":"The average result of a play if you repeated it many times. A play that is positive on average makes money in the long run, even if it loses this time.","combo":"One specific two-card holding with suits, e.g. A♠ K♥. Counting these holdings shows how many of a given hand are really in a range.","range":"The set of all hands a player can have in a given situation, or the hands they would make a given play with.","mixed-hand":"A hand with which the equilibrium strategy sometimes chooses one play and sometimes another (e.g. sometimes a raise, sometimes a call); both plays are correct. Such a hand is also said to be played with a mixed strategy.","open":"Entering the pot before the flop with a raise when everyone before you has folded.","suited":"Two hole cards of the same suit, e.g. A♥ K♥ (written AKs).","offsuit":"Two hole cards of different suits, e.g. A♥ K♣ (written AKo).","pocket-pair":"A pair made of your two hole cards, e.g. 8♣ 8♦ before the flop.","connectors":"Hole cards of adjacent ranks, e.g. 8-7 or 9-8; they make straights more easily.","3-bet":"The first raise of an open before the flop; the name counts the big blind as the first bet and the open as the second.","4-bet":"A raise of a 3-bet, i.e. the fourth bet in a betting round.","limp":"Entering the pot before the flop by just calling the big blind when nobody has raised yet.","isolation":"A raise after one or more limps, to play the limper (often a weaker player) one on one.","texture":"The character of the community cards: how many suits there are, whether the cards are close together, whether there is a pair. It determines which hands and draws are possible.","dry":"A board on which few draws and strong hands are possible, e.g. K♠ 7♦ 2♣.","wet":"A board on which many draws and strong hands are possible, e.g. J♥ T♥ 8♣.","rainbow":"A flop with three cards of three different suits, so nobody has a flush draw on the flop.","two-tone":"A flop with two cards of the same suit, so flush draws are possible.","monotone":"A flop with three cards of the same suit, so a flush may already be made.","paired":"A board with a pair on it (two cards of the same rank), e.g. 8-8-3.","connected":"A board on which someone may already have made a straight, e.g. 9-8-7.","disconnected":"A board with cards far apart, making it hard to build a straight or a straight draw, e.g. K-7-2.","semi-connected":"A board with straight draws but no straight possible yet, e.g. T-8-3 (the classification used in this course).","wetness":"How much a board favors draws and strong hands: from dry to wet. It is also described as how coordinated the board is.","top-pair":"A pair with the highest card on the board, e.g. K♠ Q♦ on a K-7-2 flop.","second-pair":"A pair with the second-highest card on the board, e.g. 7♠ 6♠ on a K-7-2 flop.","overpair":"A pocket pair higher than every card on the board, e.g. Q-Q on a J-7-2 flop.","c-bet":"Continuation bet: a bet by the player who was the aggressor in the previous round, e.g. a bet on the flop after opening preflop.","aggressor":"The player who last bet or raised in the previous betting round.","initiative":"The role of the last aggressor: they usually make the next bet.","range-advantage":"A situation where one player's range has more total equity on a given board than the opponent's range.","nuts-advantage":"A situation where one player has proportionally more of the strongest hands in their range than the opponent.","nuts":"The strongest possible hand on a given board at a given moment. Example: on K♥ 9♥ 4♥ 2♣ it is the ace-high flush (with the ace of hearts).","polarized":"Of a range: made up mainly of very strong hands and bluffs, with almost no medium hands.","polarization":"Building a range from the extremes: strong hands for value and bluffs, without medium hands.","linear":"Of a range: built from the top down, from the strongest hands, with no separate group of bluffs. You will also see the related term “merged range” (a non-polarized range); according to published solver analyses, merged is an intermediate shape between this range and a polarized one.","condensed":"Of a range: without the strongest hands (capped) and made up mainly of medium hands; the opposite of polarized.","value":"Betting with a strong hand so that the opponent calls with a weaker hand.","value-bet":"A single bet for value: made with a strong hand so that weaker hands call it.","bluff":"A bet with a weak hand that is unlikely to win at showdown, to make the opponent fold a better hand.","semi-bluff":"A bet with a hand that is still weak but can improve (e.g. with a draw): you win if the opponent folds or if you hit.","blocker":"A card in your hand that lowers the chance that the opponent has certain hands. Example: if you hold the ace of hearts, the opponent cannot have the ace-high heart flush.","bluff-catcher":"A hand that beats only the opponent's bluffs and loses to their value bets.","barrel":"Another bet in the next betting round after your own bet in the previous round.","second-barrel":"A second bet in a row: after a c-bet on the flop, the player bets again on the turn.","probe-bet":"A turn bet by the out-of-position player after the preflop aggressor checked the flop instead of making a c-bet.","donk-bet":"A bet by a player who bets before the aggressor from the previous round has had a chance to act.","overbet":"A bet after the flop that is larger than the whole pot.","effective-stack":"In a hand between two players: the smaller of their stacks, i.e. the most that can realistically be won or lost. With several players, it is calculated separately for each pair.","spr":"The effective stack divided by the pot at the start of a street (for planning the hand, it is calculated on the flop); it shows how deep the stacks are relative to the pot (the lower the SPR, the faster everything goes into the pot).","mdf":"The smallest part of your range you must defend against a bet so that an opponent's bluff with a hand that has no chance is not automatically profitable.","alpha":"How often the opponent must fold for a bluff with a hand that has no chance to break even; it depends on the bet size relative to the pot.","variance":"The spread of results around expected value: even with good play, short stretches can show big losses or big wins.","buy-in":"The amount it costs to enter a tournament or to sit in a cash game.","bankroll":"Your whole reserve set aside only for playing poker; in this app it is counted in buy-ins, not money.","tilt":"A state in which emotions (anger, frustration, euphoria) make your decisions at the table worse.","winrate":"A player's average result over a longer sample; in cash games usually in bb/100, i.e. big blinds per hundred hands.","downswing":"A period of clearly worse results, usually bigger losses than skill would suggest; the opposite of an upswing.","session":"One sitting of poker, from when you start playing to when you stop.","stakes":"The size of the blinds in a cash game or the buy-in in a tournament; “micro stakes” are the lowest levels.","standard-deviation":"A measure of the spread of results (the square root of variance); in poker usually given in bb/100.","risk-of-ruin":"The probability that you will ever lose your whole bankroll if you keep playing at the same stakes.","mental-game":"The psychological side of poker: dealing with tilt, emotions and focus at the table.","tournament":"A format in which the blinds go up at intervals and play continues until one player has all the chips; prizes go to the highest finishers.","push-fold":"A simplified strategy for short stacks: before the flop you either go all-in or fold.","shove":"An all-in play, usually as a raise before the flop.","icm":"A model that converts tournament chips into money value, taking into account the payout structure and all players' stacks.","bubble":"The stage of a tournament just before the paid places, when a few more players need to bust before anyone is in the money.","bubble-factor":"An ICM measure: how much more losing a given number of chips hurts in a tournament than winning the same number helps.","cover":"To have at least as many chips as the opponent. When an opponent covers you, losing an all-in to them ends your tournament.","risk-premium":"Extra equity beyond what pot odds require, needed in a tournament to risk an all-in, because losing costs more than winning gains.","m-ratio":"Your stack divided by the total of blinds and antes in one hand: how many full orbits your chips will last without playing.","red-zone":"The zone of very low M: you are left mainly with all-in or fold.","green-zone":"The zone of high M: your stack lets you play freely, cautiously or aggressively.","ante":"A small forced payment into the pot before the deal from every player (mainly in tournaments).","bb-ante":"An ante format in which, instead of every player, the player in the big blind pays the ante for the whole table.","fold-equity":"The part of a play's value that comes from the chance that the opponent folds.","gap-concept":"The principle that you need a stronger hand to call an open than to open yourself.","chip-ev":"The expected value of a play counted in chips, without converting them into money (without ICM).","tournament-equity":"Your expected share of the prize pool given the payout structure and stacks. It is also called “$EV”.","prize-pool":"The total money to be shared among the players who win prizes in a tournament.","payout":"The prize for a specific finishing place in a tournament; together they make up the prize distribution.","pay-jump":"The difference in payout between adjacent places in a tournament; big jumps increase the risk premium.","final-table":"The last table of a tournament, where the top prizes are played for.","short-stack":"A stack that is small relative to the blinds; in tournaments usually one with only a few big blinds left.","nash-equilibrium":"A set of strategies in which no player can gain by changing only their own strategy.","overcall":"Calling a bet that someone before you has already called.","heads-up":"Playing one on one: only two players are left at the table or in the hand.","dead-money":"Chips in the pot from players who can no longer win it, e.g. from those who folded.","stack-off":"To put your whole stack into the pot in one hand, i.e. to go all-in or call an all-in.","exploit":"A deliberate departure from the baseline strategy to take advantage of a specific mistake by an opponent or by the whole player pool.","hud":"An overlay on the table in online play that shows opponents' statistics from previously played hands.","vpip":"A HUD statistic: the percentage of hands in which a player voluntarily puts money into the pot before the flop (calls or raises).","pfr":"A HUD statistic: the percentage of hands in which a player raises before the flop.","wtsd":"A HUD statistic: how often a player who saw the flop gets to showdown.","nit":"A very tight player who enters the pot almost only with strong hands.","regular":"A frequent player at a given stakes level who plays a lot of hands; in this course contrasted with the recreational player.","tag":"A tight aggressive style: few hands, but played aggressively (bets and raises).","lag":"A loose aggressive style: many hands, played aggressively.","recreational":"A player who plays for fun and is usually weaker than the regulars; in slang, derogatorily called a “fish”.","calling-station":"A derogatory term for a player who calls very often, even with weak hands or draws.","maniac":"A derogatory term for a very loose and aggressive player who bets and raises with almost anything.","rake":"The fee a casino or online poker room takes from the pot for running the game.","rake-cap":"The maximum amount of rake a poker room can take from a single hand."},
  "fr": {"royal-flush":"La combinaison la plus forte au poker : as, roi, dame, valet et dix de la même couleur, p. ex. A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Cinq cartes consécutives de la même couleur, p. ex. 5♥ 6♥ 7♥ 8♥ 9♥. La version la plus haute (de l'as au dix) porte un nom à part et c'est la combinaison la plus forte du jeu.","four-of-a-kind":"Quatre cartes de même valeur, p. ex. quatre sept. Entre deux carrés de même valeur, c'est la cinquième carte la plus haute (le kicker) qui l'emporte.","full-house":"Un brelan et une paire dans la même main, p. ex. trois dames et deux cinq. Entre deux fulls, le brelan le plus haut l'emporte.","flush":"Cinq cartes du même symbole (♠, ♥, ♦ ou ♣) qui ne se suivent pas. Entre deux mains de ce type, celle qui a la carte la plus haute l'emporte ; à égalité, c'est la carte suivante qui décide.","straight":"Cinq cartes consécutives, pas toutes de la même couleur, p. ex. 5-6-7-8-9. L'as peut être la carte la plus haute (A-K-Q-J-T) ou la plus basse (A-2-3-4-5).","three-of-a-kind":"Trois cartes de même valeur et deux autres cartes. Au hold'em, il en existe deux variantes qui ont leur propre nom : le set, quand la paire est dans votre main et la troisième carte sur le board, et les trips, quand la paire est sur le board et la troisième carte dans votre main.","set":"Brelan formé d'une paire en main et d'une carte du board, p. ex. 7♣ 7♦ sur un flop K-7-2.","two-pair":"Deux paires différentes et une cinquième carte, p. ex. K-K-8-8-3. En cas d'égalité, on compare d'abord la paire la plus haute, puis la plus basse, et enfin la cinquième carte.","pair":"Deux cartes de même valeur et trois autres cartes, p. ex. deux neuf. Seule la carte haute est plus faible.","high-card":"Main sans paire ni meilleure combinaison ; sa force dépend de la carte la plus haute, puis des suivantes en cas d'égalité.","kicker":"La carte la plus haute en dehors de la combinaison, qui départage une égalité. Exemple : une paire d'as avec un roi bat une paire d'as avec une dame.","wheel":"La quinte la plus basse : A-2-3-4-5, où l'as compte comme la carte la plus basse.","check":"Continuer sans mettre de jetons, ce qui n'est possible que si vous n'avez rien à ajouter : personne n'a encore misé dans ce tour d'enchères (avant le flop, la grosse blinde peut le faire si personne n'a relancé). À ne pas confondre avec « suivre » (call), qui consiste à ajouter des jetons pour égaler la mise d'un adversaire.","bet":"Premiers jetons mis dans un tour d'enchères où personne n'a encore misé (au sens large, on appelle mise tous les jetons placés dans le pot).","call":"Mettre dans le pot le montant de la mise ou de la relance d'un adversaire pour continuer à jouer. À ne pas confondre avec le check, qui consiste à continuer sans miser quand personne n'a misé.","raise":"Augmenter le montant au-delà de la mise d'un adversaire ; les autres joueurs doivent ajouter la différence, relancer à leur tour ou se coucher. On dit aussi « raise ».","fold":"Abandonner la main : vous jetez vos cartes et perdez ce que vous avez déjà mis dans le pot.","check-raise":"Vous checkez d'abord, puis, quand un adversaire mise, vous le relancez dans le même tour d'enchères.","all-in":"Miser tous vos jetons. Vous ne pouvez alors gagner contre chaque adversaire qu'au maximum ce que vous avez vous-même mis ; le reste se joue dans un pot secondaire.","pot":"Tous les jetons misés dans la main en cours. Ils reviennent au joueur qui a la meilleure main au showdown (avec des pots secondaires, chaque pot est attribué séparément) ou au joueur qui reste quand tous les autres se sont couchés.","side-pot":"Pot séparé créé quand un joueur est all-in : seuls les joueurs qui ont mis plus que lui le disputent, donc le joueur all-in ne peut pas le gagner.","split-pot":"Situation où des joueurs ayant des mains égales se partagent le pot, p. ex. quand tous deux jouent la même quinte présente sur le board.","playing-the-board":"Situation où votre meilleure main de cinq cartes n'est composée que de cartes communes ; vos cartes privatives n'apportent rien, donc au mieux vous partagez le pot.","board":"Les cartes communes visibles au centre (flop, turn, river), utilisées par tous les joueurs. Le terme désigne les cartes, pas la table où l'on joue (s'asseoir à la table, table finale).","community-cards":"Cartes posées face visible au centre, que chaque joueur peut utiliser pour former sa main ; au hold'em, il y en a cinq.","hole-cards":"Les deux cartes face cachée que vous recevez au début d'une main au hold'em ; vous seul les voyez.","small-blind":"La plus petite mise obligatoire, posée avant la donne par le joueur à gauche du bouton (à deux joueurs, par le bouton lui-même) ; c'est aussi le nom de cette place à la table.","big-blind":"La plus grosse mise obligatoire, posée avant la donne par le deuxième joueur à gauche du bouton (à deux joueurs, par le joueur face au bouton) ; c'est aussi le nom de cette place. Elle sert aussi d'unité pour mesurer les stacks et les résultats.","chips":"Les disques avec lesquels on joue à la table ; en cash game, ils représentent de l'argent, en tournoi, des points de tournoi.","stack":"Tous les jetons qu'un joueur a devant lui ; on l'exprime généralement en grosses blindes (p. ex. 100 grosses blindes).","street":"Nom familier d'un tour d'enchères : le preflop, le flop, le turn et la river sont les quatre streets. Exemple : « de la value sur trois streets » désigne des mises de value au flop, au turn et à la river.","betting-round":"Étape de la main où les joueurs, chacun leur tour, checkent, misent, suivent, relancent ou se couchent ; au hold'em, il y en a quatre : preflop, flop, turn et river.","preflop":"Le premier tour d'enchères : après la distribution des cartes privatives, avant l'arrivée du flop.","flop":"Les trois premières cartes communes, posées ensemble après les enchères du preflop ; c'est aussi le nom du deuxième tour d'enchères.","turn":"La quatrième carte commune et le troisième tour d'enchères.","river":"La cinquième et dernière carte commune, et le dernier tour d'enchères avant le showdown.","showdown":"Le moment où l'on dévoile les cartes après le dernier tour d'enchères, quand au moins deux joueurs sont encore dans la main ; la meilleure main remporte le pot.","position":"Votre place à la table par rapport au bouton, qui fixe l'ordre de parole. Celui qui parle plus tard voit davantage d'actions adverses avant de décider.","in-position":"Situation du joueur qui parle en dernier après le flop et voit donc l'action de l'adversaire avant de décider.","out-of-position":"Situation du joueur qui parle avant l'adversaire après le flop et décide donc sans connaître son action.","early-position":"Les premières places à parler avant le flop (p. ex. UTG) ; beaucoup de joueurs doivent encore parler après vous.","late-position":"Les places qui parlent en dernier : le bouton et les places juste avant lui, surtout le cutoff.","utg":"Le premier joueur à parler avant le flop, assis juste à gauche de la grosse blinde.","hijack":"La place juste avant le cutoff, c'est-à-dire la deuxième à droite du bouton.","cutoff":"La place juste à droite du bouton, qui parle juste avant lui.","button":"La place du donneur, marquée par un disque « dealer ». Après le flop, elle parle en dernier à chaque tour d'enchères.","outs":"Carte encore dans le paquet qui améliorera votre main, généralement en complétant un tirage. Exemple : avec un tirage couleur, vos outs sont les cartes restantes de votre couleur.","draw":"Main qui n'est pas encore une combinaison forte mais peut le devenir avec les prochaines cartes communes, p. ex. quand il vous manque une carte pour une couleur ou une quinte.","flush-draw":"Quatre cartes de la même couleur (en main et sur le board réunis) ; il en manque une pour avoir une couleur.","straight-draw":"Quatre cartes auxquelles il en manque une pour faire une quinte. Variantes : OESD (la carte manquante peut être à l'un des deux bouts) et gutshot (la carte manque au milieu).","oesd":"Abréviation de open-ended straight draw : tirage quinte formé de quatre cartes consécutives, complété par une carte à l'un ou l'autre bout, p. ex. 5-6-7-8 attend un quatre ou un neuf.","gutshot":"Tirage quinte auquel il manque une valeur précise au milieu, p. ex. 5-6-8-9 n'attend qu'un sept.","backdoor":"Tirage au flop qui a besoin de deux cartes favorables d'affilée, au turn et à la river, p. ex. trois cartes de la même couleur après le flop.","pot-odds":"Rapport entre le montant que vous devez payer et le pot que vous pouvez gagner (mise adverse comprise). Il indique à quelle fréquence vous devez gagner pour que suivre soit rentable.","implied-odds":"La cote du pot augmentée des jetons que vous comptez gagner sur les streets suivantes si vous touchez votre main.","equity":"Votre chance de remporter le pot si toutes les cartes restantes étaient distribuées sans autres enchères ; généralement exprimée en pourcentage.","equity-realization":"La mesure dans laquelle une main transforme son équité en gains quand les enchères continuent (elle peut en réaliser moins ou plus que son équité) ; cela dépend notamment de la position et de la facilité à jouer la main.","expected-value":"Le résultat moyen d'une action si on la répétait de nombreuses fois. Une action positive en moyenne rapporte sur le long terme, même si elle perd cette fois-ci.","combo":"Une combinaison précise de deux cartes avec leurs couleurs, p. ex. A♠ K♥. Compter ces combinaisons montre combien de mains d'un type donné figurent réellement dans une range.","range":"L'ensemble des mains qu'un joueur peut avoir dans une situation donnée, ou des mains avec lesquelles il ferait une action donnée.","mixed-hand":"Main avec laquelle la stratégie d'équilibre choisit tantôt une action, tantôt une autre (p. ex. parfois une relance, parfois un call) ; les deux actions sont correctes. On dit aussi qu'une telle main se joue en stratégie mixte.","open":"Entrer dans le pot avant le flop par une relance quand tous les joueurs avant vous se sont couchés.","suited":"Deux cartes privatives de la même couleur, p. ex. A♥ K♥ (notation AKs).","offsuit":"Deux cartes privatives de couleurs différentes, p. ex. A♥ K♣ (notation AKo).","pocket-pair":"Paire formée par vos deux cartes privatives, p. ex. 8♣ 8♦ avant le flop.","connectors":"Cartes privatives de valeurs voisines, p. ex. 8-7 ou 9-8 ; elles forment plus facilement une quinte.","3-bet":"La première relance d'une ouverture avant le flop ; le nom compte la grosse blinde comme première mise et l'ouverture comme deuxième.","4-bet":"Relance d'un 3-bet, c'est-à-dire la quatrième mise du tour d'enchères.","limp":"Entrer dans le pot avant le flop en se contentant de suivre la grosse blinde, quand personne n'a encore relancé.","isolation":"Relance après un ou plusieurs limps, pour jouer contre le limpeur (souvent un joueur plus faible) en tête-à-tête.","texture":"Le caractère des cartes communes : combien de couleurs il y a, si les cartes sont proches les unes des autres, s'il y a une paire. Cela détermine les mains et les tirages possibles.","dry":"Board sur lequel peu de tirages et de mains fortes sont possibles, p. ex. K♠ 7♦ 2♣.","wet":"Board sur lequel de nombreux tirages et mains fortes sont possibles, p. ex. J♥ T♥ 8♣.","rainbow":"Flop dont les trois cartes sont de trois couleurs différentes, si bien que personne n'a de tirage couleur au flop.","two-tone":"Flop dont deux cartes sont de la même couleur, si bien que des tirages couleur sont possibles.","monotone":"Flop dont les trois cartes sont de la même couleur, si bien qu'une couleur peut déjà être faite.","paired":"Board sur lequel il y a une paire (deux cartes de même valeur), p. ex. 8-8-3.","connected":"Board sur lequel quelqu'un a déjà pu faire une quinte, p. ex. 9-8-7.","disconnected":"Board aux cartes éloignées les unes des autres, avec lequel il est difficile de former une quinte ou un tirage quinte, p. ex. K-7-2.","semi-connected":"Board sur lequel il existe des tirages quinte, mais où aucune quinte n'est encore possible, p. ex. T-8-3 (classification adoptée dans ce cours).","wetness":"Le degré auquel un board favorise les tirages et les mains fortes : de sec à humide. On parle aussi du degré de coordination du board.","top-pair":"Paire formée avec la carte la plus haute du board, p. ex. K♠ Q♦ sur un flop K-7-2.","second-pair":"Paire formée avec la deuxième carte la plus haute du board, p. ex. 7♠ 6♠ sur un flop K-7-2.","overpair":"Paire servie supérieure à toutes les cartes du board, p. ex. Q-Q sur un flop J-7-2.","c-bet":"Mise de continuation : mise du joueur qui était l'agresseur au tour précédent, p. ex. une mise au flop après avoir ouvert au preflop.","aggressor":"Le joueur qui a misé ou relancé en dernier au tour d'enchères précédent.","initiative":"Le rôle du dernier agresseur : c'est généralement lui qui fait la mise suivante.","range-advantage":"Situation où la range d'un joueur a, sur un board donné, une équité totale supérieure à celle de la range adverse.","nuts-advantage":"Situation où un joueur a proportionnellement plus de mains parmi les plus fortes dans sa range que l'adversaire.","nuts":"La main la plus forte possible sur un board donné à un moment donné. Exemple : sur le board K♥ 9♥ 4♥ 2♣, c'est la couleur à l'as de cœur.","polarized":"Se dit d'une range composée surtout de mains très fortes et de bluffs, presque sans mains moyennes.","polarization":"Construire une range à partir des extrêmes : mains fortes pour la value et bluffs, sans mains moyennes.","linear":"Se dit d'une range construite par le haut, des mains les plus fortes vers le bas, sans groupe de bluffs à part. On rencontre aussi le terme apparenté « merged range » (range non polarisée) ; selon les analyses de solveur publiées, merged est une forme intermédiaire entre cette range et une range polarisée.","condensed":"Se dit d'une range sans les mains les plus fortes (plafonnée) et composée surtout de mains moyennes ; le contraire d'une range polarisée.","value":"Miser avec une main forte pour que l'adversaire suive avec une main plus faible.","value-bet":"Une mise isolée pour la value : faite avec une main forte pour que des mains plus faibles la suivent.","bluff":"Mise avec une main faible qui a peu de chances de gagner au showdown, pour que l'adversaire couche une meilleure main.","semi-bluff":"Mise avec une main encore faible mais qui peut s'améliorer (p. ex. avec un tirage) : vous gagnez si l'adversaire se couche ou si vous touchez.","blocker":"Carte de votre main qui réduit la probabilité que l'adversaire ait certaines mains. Exemple : si vous avez l'as de cœur, l'adversaire ne peut pas avoir la couleur à l'as de cœur.","bluff-catcher":"Main qui ne bat que les bluffs de l'adversaire et perd contre ses mises de value.","barrel":"Nouvelle mise au tour d'enchères suivant, après votre propre mise au tour précédent.","second-barrel":"Deuxième mise d'affilée : après un c-bet au flop, le joueur mise de nouveau au turn.","probe-bet":"Mise au turn du joueur hors de position après que l'agresseur preflop a checké le flop au lieu de faire un c-bet.","donk-bet":"Mise d'un joueur qui mise avant que l'agresseur du tour précédent ait pu agir.","overbet":"Mise après le flop supérieure à la totalité du pot.","effective-stack":"Dans une main entre deux joueurs : le plus petit de leurs deux stacks, c'est-à-dire le maximum qui peut réellement être gagné ou perdu. Avec plusieurs joueurs, on le calcule séparément pour chaque paire.","spr":"Le stack effectif divisé par le pot au début d'une street (pour planifier la main, on le calcule au flop) ; il indique la profondeur des stacks par rapport au pot (plus le SPR est bas, plus vite tout finit dans le pot).","mdf":"La plus petite part de la range qu'il faut défendre face à une mise pour qu'un bluff adverse avec une main sans chance ne soit pas automatiquement rentable.","alpha":"La fréquence à laquelle l'adversaire doit se coucher pour qu'un bluff avec une main sans chance soit à l'équilibre ; elle dépend de la taille de la mise par rapport au pot.","variance":"La dispersion des résultats autour de l'espérance de gain : même en jouant bien, les courtes séries peuvent être fortement négatives ou positives.","buy-in":"Le montant à payer pour entrer dans un tournoi ou s'asseoir à une table de cash game.","bankroll":"Toute la réserve consacrée uniquement au poker ; dans cette application, elle se compte en buy-ins, pas en argent.","tilt":"État dans lequel les émotions (colère, frustration, euphorie) dégradent vos décisions à la table.","winrate":"Résultat moyen d'un joueur sur un long échantillon ; en cash game, généralement en bb/100, c'est-à-dire en grosses blindes pour cent mains.","downswing":"Période de résultats nettement moins bons, généralement des pertes plus fortes que ce que justifierait le niveau de jeu ; le contraire d'un upswing.","session":"Une séance de poker, du début à la fin du jeu.","stakes":"Le niveau des blindes en cash game ou du buy-in en tournoi ; les « micro-limites » sont les niveaux les plus bas.","standard-deviation":"Mesure de la dispersion des résultats (racine carrée de la variance) ; au poker, généralement exprimée en bb/100.","risk-of-ruin":"Probabilité de perdre un jour toute votre bankroll si vous continuez à jouer à la même limite.","mental-game":"Le côté psychologique du poker : gérer le tilt, les émotions et la concentration à la table.","tournament":"Format de jeu où les blindes augmentent à intervalles réguliers et où la partie dure jusqu'à ce qu'un joueur ait tous les jetons ; les mieux classés reçoivent des prix.","push-fold":"Stratégie simplifiée pour les short stacks : avant le flop, on part soit all-in, soit on se couche.","shove":"Le fait de partir all-in, généralement sous forme de relance avant le flop.","icm":"Modèle qui convertit les jetons de tournoi en valeur monétaire en tenant compte de la structure des gains et des stacks de tous les joueurs.","bubble":"Phase d'un tournoi juste avant les places payées, quand il ne reste que quelques joueurs à éliminer avant d'atteindre les prix.","bubble-factor":"Indicateur issu de l'ICM : à quel point, en tournoi, perdre un nombre de jetons fait plus mal que gagner le même nombre ne fait du bien.","cover":"Avoir au moins autant de jetons que l'adversaire. Quand un adversaire vous couvre, perdre un all-in contre lui met fin à votre tournoi.","risk-premium":"Équité supplémentaire, au-delà de ce qu'exige la cote du pot, nécessaire en tournoi pour risquer un all-in, car perdre coûte plus que gagner ne rapporte.","m-ratio":"Le stack divisé par la somme des blindes et des antes d'une main : le nombre de tours de table complets (orbites) que vos jetons permettent de tenir sans jouer.","red-zone":"Zone de M très bas : il ne reste guère que le choix entre all-in et se coucher.","green-zone":"Zone de M élevé : le stack permet de jouer librement, de façon prudente ou agressive.","ante":"Petite contribution obligatoire au pot versée avant la donne par tous les joueurs (surtout en tournoi).","bb-ante":"Format d'ante dans lequel, au lieu de tous les joueurs, c'est le joueur en grosse blinde qui paie l'ante pour toute la table.","fold-equity":"Part de la valeur d'une action qui vient de la possibilité que l'adversaire se couche.","gap-concept":"Principe selon lequel il faut une main plus forte pour suivre une ouverture que pour ouvrir soi-même.","chip-ev":"Espérance de gain d'une action comptée en jetons, sans les convertir en argent (sans ICM).","tournament-equity":"Votre part attendue du prize pool compte tenu de la structure des gains et des stacks. On l'appelle aussi « $EV ».","prize-pool":"Somme d'argent à répartir entre les joueurs primés d'un tournoi.","payout":"Le prix attribué à une place précise dans un tournoi ; l'ensemble forme la répartition des prix.","pay-jump":"Différence de gains entre deux places voisines d'un tournoi ; les gros sauts augmentent la prime de risque.","final-table":"La dernière table d'un tournoi, où se jouent les plus gros prix.","short-stack":"Stack petit par rapport aux blindes ; en tournoi, généralement un stack qui ne représente plus que peu de grosses blindes.","nash-equilibrium":"Ensemble de stratégies dans lequel aucun joueur ne peut gagner en modifiant uniquement sa propre stratégie.","overcall":"Suivre une mise qu'un joueur avant vous a déjà suivie.","heads-up":"Jeu en tête-à-tête : il ne reste que deux joueurs à la table ou dans la main.","dead-money":"Jetons du pot provenant de joueurs qui ne peuvent plus le gagner, p. ex. de ceux qui se sont couchés.","stack-off":"Mettre tout son stack dans le pot au cours d'une main, c'est-à-dire partir all-in ou suivre un all-in.","exploit":"Écart volontaire par rapport à la stratégie de base pour profiter d'une erreur précise d'un adversaire ou de l'ensemble des joueurs.","hud":"Affichage superposé à la table en ligne, qui montre les statistiques des adversaires sur les mains jouées précédemment.","vpip":"Statistique du HUD : le pourcentage de mains où un joueur met volontairement de l'argent dans le pot avant le flop (en suivant ou en relançant).","pfr":"Statistique du HUD : le pourcentage de mains où un joueur relance avant le flop.","wtsd":"Statistique du HUD : la fréquence à laquelle un joueur qui a vu le flop va jusqu'au showdown.","nit":"Joueur très serré qui n'entre dans le pot presque qu'avec des mains fortes.","regular":"Habitué d'une limite donnée, qui joue beaucoup de mains ; dans ce cours, il est opposé au joueur récréatif.","tag":"Style serré-agressif : peu de mains, mais jouées agressivement (mises et relances).","lag":"Style large-agressif : beaucoup de mains, jouées agressivement.","recreational":"Joueur qui joue pour le plaisir et généralement moins bien que les habitués ; en argot, péjorativement, « fish ».","calling-station":"Terme péjoratif pour un joueur qui suit très souvent, même avec des mains faibles ou des tirages.","maniac":"Terme péjoratif pour un joueur très large et agressif, qui mise et relance avec n'importe quoi.","rake":"Commission que le casino ou la salle en ligne prélève sur le pot pour organiser la partie.","rake-cap":"Montant maximal de rake qu'une salle peut prélever sur une seule main."},
  "ja": {"royal-flush":"ポーカーで最も強い役です。同じスートのエース、キング、クイーン、ジャック、10の5枚で、例：A♠ K♠ Q♠ J♠ T♠。","straight-flush":"同じスートで連続する5枚のカードです。例：5♥ 6♥ 7♥ 8♥ 9♥。最も高いもの（エースから10まで）には別の名前があり、ゲームで最も強い役です。","four-of-a-kind":"同じランクのカード4枚です。例：7が4枚。同じランクのフォーカード同士では、5枚目のカード（キッカー）が高いほうが勝ちます。","full-house":"スリーカードとペアを組み合わせた役です。例：クイーン3枚と5が2枚。フルハウス同士では、スリーカードが高いほうが勝ちます。","flush":"同じスート（♠、♥、♦、♣のいずれか）の5枚で、連続していないものです。フラッシュ同士では最も高いカードが高いほうが勝ち、同じなら次に高いカードで決まります。","straight":"連続する5枚のカードで、すべてが同じスートではないものです。例：5-6-7-8-9。エースは最も高いカード（A-K-Q-J-T）にも、最も低いカード（A-2-3-4-5）にもなります。","three-of-a-kind":"同じランクのカード3枚とほかのカード2枚です。ホールデムでは別の名前を持つ2種類があります。ペアが手札にあり3枚目がボードにあるときはセット、ペアがボードにあり3枚目が手札にあるときはトリップスです。","set":"手札のペアとボードの1枚でできたスリーカードです。例：K-7-2のフロップで7♣ 7♦。","two-pair":"異なる2組のペアと5枚目のカードです。例：K-K-8-8-3。同じ場合は、まず高いほうのペア、次に低いほうのペア、最後に5枚目のカードで決まります。","pair":"同じランクのカード2枚とほかのカード3枚です。例：9が2枚。これより弱いのはハイカードだけです。","high-card":"ペア以上の組み合わせがない役です。強さは最も高いカードで決まり、同じなら次のカードで決まります。","kicker":"役に含まれないカードのうち最も高いもので、引き分けを決めます。例：エースのペアにキングがある手は、エースのペアにクイーンがある手に勝ちます。","wheel":"最も低いストレートで、A-2-3-4-5です。エースは最も低いカードとして数えます。","check":"チップを出さずにプレイを続けることです。追加で払う必要がないとき、つまりこのベッティングラウンドでまだ誰もベットしていないときだけできます（フロップ前は、誰もレイズしていなければビッグブラインドがチェックできます）。相手のベットに額を合わせるコールと混同しないでください。","bet":"まだ誰もベットしていないベッティングラウンドで、最初にチップを出すことです（広い意味では、ポットにチップを入れることすべてをベットと呼びます）。","call":"プレイを続けるために、相手のベットまたはレイズと同じ額をポットに入れることです。誰もベットしていないときにベットせずに続けるチェックと混同しないでください。","raise":"相手のベットより額を引き上げることです。ほかのプレイヤーは差額を出すか、さらにレイズするか、フォールドしなければなりません。","fold":"そのハンドを降りることです。カードを捨て、すでにポットに入れたチップは失います。","check-raise":"まずチェックし、相手がベットしたら、同じベッティングラウンドでレイズすることです。","all-in":"自分のチップをすべて賭けることです。各相手から勝てるのは最大で自分が入れた額までで、残りはサイドポットで争われます。","pot":"現在のハンドで賭けられたチップすべてです。ショーダウンで最も強い役のプレイヤー（サイドポットがあればポットごとに別々に決まります）か、ほかの全員がフォールドしたときに残ったプレイヤーが獲得します。","side-pot":"誰かがオールインしたときにできる別のポットです。オールインしたプレイヤーより多く入れたプレイヤーだけがこれを争うため、オールインしたプレイヤー自身は獲得できません。","split-pot":"同じ強さの役を持つプレイヤーがポットを分け合う状況です。例：2人ともボード上の同じストレートでプレイしている場合。","playing-the-board":"自分の最も強い5枚の役がコミュニティカードだけでできている状況です。ホールカードが何も加えないため、よくてもポットを分け合うことになります。","board":"中央に表向きに置かれ、全プレイヤーが使うコミュニティカード（フロップ、ターン、リバー）です。プレイする卓（テーブル）ではなく、カードのことを指します。","community-cards":"中央に表向きに配られ、どのプレイヤーも自分の役に使えるカードです。ホールデムでは5枚あります。","hole-cards":"ホールデムでハンドの最初に配られる裏向きの2枚のカードです。見られるのは自分だけです。","small-blind":"配る前に、ボタンの左隣のプレイヤー（2人のときはボタン自身）が出す小さいほうの強制ベットです。その席もこう呼びます。","big-blind":"配る前に、ボタンから左に2番目のプレイヤー（2人のときはボタンの相手）が出す大きいほうの強制ベットです。その席もこう呼びます。スタックの大きさや成績の単位にも使われます。","chips":"テーブルでプレイに使う円盤です。キャッシュゲームではお金を、トーナメントではトーナメントのポイントを表します。","stack":"プレイヤーが目の前に持っているチップすべてです。通常はビッグブラインドの数で表します（例：100ビッグブラインド）。","street":"ベッティングラウンドの俗称で、プリフロップ、フロップ、ターン、リバーが4つのストリートです。例：「3ストリートでバリュー」とは、フロップ、ターン、リバーでバリューのためにベットすることです。","betting-round":"プレイヤーが順番にチェック、ベット、コール、レイズ、フォールドするハンドの段階です。ホールデムではプリフロップ、フロップ、ターン、リバーの4つがあります。","preflop":"最初のベッティングラウンドです。ホールカードが配られた後、フロップが出る前に行います。","flop":"プリフロップのベットの後にまとめて配られる最初の3枚のコミュニティカードです。2番目のベッティングラウンドもこう呼びます。","turn":"4枚目のコミュニティカードで、3番目のベッティングラウンドでもあります。","river":"5枚目で最後のコミュニティカードで、ショーダウン前の最後のベッティングラウンドでもあります。","showdown":"最後のベットの後、2人以上のプレイヤーが残っているときにカードを公開することです。最も強い役がポットを獲得します。","position":"ボタンを基準にしたテーブル上の席で、アクションの順番を決めます。後にアクションするプレイヤーほど、判断の前に相手のプレイを多く見られます。","in-position":"フロップ後に最後にアクションするプレイヤーの状況です。判断の前に相手のプレイを見られます。","out-of-position":"フロップ後に相手より先にアクションするプレイヤーの状況です。相手のプレイを知らずに判断します。","early-position":"フロップ前に最初にアクションする席です（例：UTG）。後ろにまだ多くのプレイヤーがいます。","late-position":"最後にアクションする席で、ボタンとそのすぐ前の席、特にカットオフです。","utg":"フロップ前に最初にアクションするプレイヤーで、ビッグブラインドのすぐ左に座ります。","hijack":"カットオフのすぐ前、つまりボタンから右に2番目の席です。","cutoff":"ボタンのすぐ右の席で、ボタンの直前にアクションします。","button":"「ディーラー」の円盤で示されるディーラーの席です。フロップ後はすべてのベッティングラウンドで最後にアクションします。","outs":"まだデッキに残っていて、自分の手を強くするカードです。多くの場合、ドローを完成させます。例：フラッシュドローなら、自分のスートの残りのカードがアウツです。","draw":"まだ強い役ではないものの、次のコミュニティカードで強い役になりうる手です。例：フラッシュやストレートにあと1枚足りないとき。","flush-draw":"同じスートのカードが4枚（手札とボードを合わせて）ある状態です。フラッシュにはあと1枚必要です。","straight-draw":"ストレートにあと1枚足りない4枚のカードです。種類はOESD（両端のどちらかのカードが足りない）とガットショット（中のカードが足りない）です。","oesd":"open-ended straight drawの略です。連続する4枚のストレートドローで、両端どちらのカードでも完成します。例：5-6-7-8は4か9を待っています。","gutshot":"中の特定の1ランクが足りないストレートドローです。例：5-6-8-9は7だけを待っています。","backdoor":"ターンとリバーで続けて合うカードが2枚必要な、フロップでのドローです。例：フロップ後に同じスートが3枚ある場合。","pot-odds":"出さなければならない額と、獲得できるポット（相手のベットを含む）の比率です。コールが得になるために、どのくらいの頻度で勝つ必要があるかがわかります。","implied-odds":"役が完成したときに後のストリートで獲得できると見込めるチップを加えたポットオッズです。","equity":"これ以上ベットせずに残りのカードをすべて配った場合に、ポットを獲得できる確率です。通常はパーセントで表します。","equity-realization":"ベットが続く中で、手がエクイティをどの程度勝ちに変えられるかを示します（エクイティより少なくも多くも実現しえます）。ポジションや手のプレイしやすさなどで変わります。","expected-value":"あるプレイを何度も繰り返したときの平均的な結果です。平均でプラスになるプレイは、今回負けたとしても長期的には利益を生みます。","combo":"スートを含めた2枚のカードの具体的な組み合わせ1つです。例：A♠ K♥。これを数えると、ある手が実際にレンジにいくつあるかがわかります。","range":"ある状況でプレイヤーが持ちうるすべての手、またはあるプレイをするときの手の集まりです。","mixed-hand":"均衡戦略があるときは一方のプレイ、あるときは別のプレイを選ぶ手です（例：レイズするときもあれば、コールするときもある）。どちらのプレイも正しい選択です。こうした手は混合戦略でプレイすると言います。","open":"前のプレイヤー全員がフォールドしたとき、フロップ前にレイズでポットに参加することです。","suited":"同じスートの2枚のホールカードです。例：A♥ K♥（表記はAKs）。","offsuit":"スートが異なる2枚のホールカードです。例：A♥ K♣（表記はAKo）。","pocket-pair":"2枚のホールカードでできたペアです。例：フロップ前の8♣ 8♦。","connectors":"ランクが隣り合うホールカードです。例：8-7や9-8。ストレートを作りやすい手です。","3-bet":"フロップ前のオープンに対する最初のレイズです。ビッグブラインドを1回目、オープンを2回目のベットと数えるため、この名前になっています。","4-bet":"3ベットに対するレイズで、ベッティングラウンドで4回目のベットにあたります。","limp":"まだ誰もレイズしていないとき、フロップ前にビッグブラインドにコールするだけでポットに参加することです。","isolation":"1人以上がリンプした後にするレイズで、リンプしたプレイヤー（弱いプレイヤーであることが多い）と1対1でプレイすることを狙います。","texture":"コミュニティカードの性質です。スートがいくつあるか、カードのランクが近いか、ペアがあるかなどを指します。これによって、どの役やドローがありうるかが決まります。","dry":"ありうるドローや強い役が少ないボードです。例：K♠ 7♦ 2♣。","wet":"ありうるドローや強い役が多いボードです。例：J♥ T♥ 8♣。","rainbow":"3枚がすべて異なるスートのフロップで、フロップの時点では誰もフラッシュドローを持っていません。","two-tone":"2枚が同じスートのフロップで、フラッシュドローがありえます。","monotone":"3枚がすべて同じスートのフロップで、すでにフラッシュができている可能性があります。","paired":"ペア（同じランクのカード2枚）があるボードです。例：8-8-3。","connected":"誰かがすでにストレートを作っている可能性があるボードです。例：9-8-7。","disconnected":"カードのランクが離れていて、ストレートやストレートドローを作りにくいボードです。例：K-7-2。","semi-connected":"ストレートドローはあるものの、まだストレートはできないボードです。例：T-8-3（このコースでの分類）。","wetness":"ボードがドローや強い役をどれだけ生みやすいかの度合いで、ドライからウェットまであります。ボードがどれだけコーディネートしているか、とも表現します。","top-pair":"ボードで最も高いカードとのペアです。例：K-7-2のフロップでK♠ Q♦。","second-pair":"ボードで2番目に高いカードとのペアです。例：K-7-2のフロップで7♠ 6♠。","overpair":"ボードのどのカードよりも高いポケットペアです。例：J-7-2のフロップでQ-Q。","c-bet":"継続ベット（コンティニュエーションベット）です。前のラウンドでアグレッサーだったプレイヤーのベットで、例：プリフロップでオープンした後のフロップでのベット。","aggressor":"前のベッティングラウンドで最後にベットまたはレイズしたプレイヤーです。","initiative":"最後のアグレッサーが持つ役割で、通常は次のベットもそのプレイヤーがします。","range-advantage":"あるボードで、一方のプレイヤーのレンジが全体として相手のレンジより高いエクイティを持つ状況です。","nuts-advantage":"一方のプレイヤーのレンジに、相手より割合として多くの最も強い手が含まれる状況です。","nuts":"そのボードでその時点で最も強い手です。例：K♥ 9♥ 4♥ 2♣のボードでは、ハートのエースを使ったフラッシュがナッツです。","polarized":"レンジについて：主にとても強い手とブラフでできていて、中くらいの手がほとんどない状態です。","polarization":"両極端でレンジを組むことです。バリューのための強い手とブラフで構成し、中くらいの手は含めません。","linear":"レンジについて：最も強い手から順に上から組まれ、ブラフの独立したグループがない状態です。関連する用語として「マージドレンジ」（ポラライズされていないレンジ）もあり、公開されたソルバー分析によれば、マージドはこのレンジとポラライズドレンジの中間の形です。","condensed":"レンジについて：最も強い手がなく（上限があり）、主に中くらいの手でできている状態です。ポラライズドの反対です。","value":"相手に弱い手でコールさせるために、強い手でベットすることです。","value-bet":"バリューのための1回のベットです。弱い手にコールさせるために、強い手で行います。","bluff":"ショーダウンでは勝てそうにない弱い手でベットし、相手に強い手をフォールドさせることです。","semi-bluff":"まだ弱いものの強くなる可能性がある手（例：ドロー）でするベットです。相手がフォールドするか、カードが当たれば勝てます。","blocker":"相手が特定の手を持つ可能性を下げる、自分の手札のカードです。例：自分がハートのエースを持っていれば、相手はハートのエースを使ったフラッシュを持てません。","bluff-catcher":"相手のブラフにだけ勝ち、相手のバリューベットには負ける手です。","barrel":"前のラウンドで自分がベットした後、次のベッティングラウンドでさらにするベットです。","second-barrel":"2回連続のベットです。フロップでCベットした後、ターンでもう一度ベットします。","probe-bet":"プリフロップのアグレッサーがフロップでCベットせずにチェックした後、アウトオブポジションのプレイヤーがターンでするベットです。","donk-bet":"前のラウンドのアグレッサーがアクションする前に、ほかのプレイヤーがするベットです。","overbet":"フロップ以降のベットで、ポット全体より大きいものです。","effective-stack":"2人のハンドでは、2人のスタックのうち小さいほうで、実際に勝ったり負けたりできる最大額です。プレイヤーが複数いるときは、2人の組ごとに別々に計算します。","spr":"エフェクティブスタックをストリート開始時のポットで割った値です（ハンドの計画にはフロップで計算します）。ポットに対してスタックがどれだけ深いかを示し、SPRが低いほど早くすべてがポットに入ります。","mdf":"勝ち目のない手での相手のブラフが自動的に得にならないように、ベットに対して守る必要があるレンジの最小の割合です。","alpha":"勝ち目のない手でのブラフが損益ゼロになるために、相手がフォールドしなければならない頻度です。ポットに対するベットの大きさで決まります。","variance":"期待値を中心とした結果のばらつきです。よいプレイをしていても、短い期間では大きなマイナスやプラスになることがあります。","buy-in":"トーナメント、またはキャッシュゲームのテーブルに参加するための金額です。","bankroll":"ポーカーのプレイだけに充てる資金全体です。このアプリではお金ではなく、バイインの数で数えます。","tilt":"感情（怒り、苛立ち、高揚感）のせいで、テーブルでの判断が悪くなる状態です。","winrate":"長めのサンプルでのプレイヤーの平均的な成績です。キャッシュゲームでは通常bb/100、つまり100ハンドあたりのビッグブラインドで表します。","downswing":"成績がはっきり悪い期間で、通常は実力から考えられるより大きな負けが続きます。アップスイングの反対です。","session":"ポーカーのプレイ1回分で、始めてから終えるまでです。","stakes":"キャッシュゲームのブラインドの額、またはトーナメントのバイインの額です。「マイクロステークス」は最も低いレベルです。","standard-deviation":"結果のばらつきを示す尺度（分散の平方根）です。ポーカーでは通常bb/100で表します。","risk-of-ruin":"同じステークスでプレイを続けた場合に、いつかバンクロールをすべて失う確率です。","mental-game":"ポーカーの心理面で、ティルト、感情、テーブルでの集中への対処を指します。","tournament":"一定時間ごとにブラインドが上がり、1人のプレイヤーがすべてのチップを集めるまで続く形式です。賞金は上位のプレイヤーが受け取ります。","push-fold":"ショートスタック向けの単純化した戦略で、フロップ前はオールインかフォールドのどちらかだけを選びます。","shove":"オールインするプレイで、通常はフロップ前のレイズとして行います。","icm":"賞金構造と全プレイヤーのスタックを考慮して、トーナメントのチップを金銭的な価値に換算するモデルです。","bubble":"トーナメントで入賞圏のすぐ手前の段階で、賞金圏に入るまであと数人の脱落が必要なときです。","bubble-factor":"ICMから得られる指標で、トーナメントで同じ数のチップを失う痛手が、得る利益よりどれだけ大きいかを示します。","cover":"相手と同じかそれ以上のチップを持っていることです。相手にカバーされているとき、その相手にオールインで負けるとトーナメントが終わります。","risk-premium":"トーナメントでオールインのリスクを取るために、ポットオッズが求める以上に必要な追加のエクイティです。負けたときの損失が、勝ったときの利益より大きいためです。","m-ratio":"スタックを1ハンドのブラインドとアンティの合計で割った値で、プレイしなくてもチップが何周（オービット）分もつかを示します。","red-zone":"Mがとても低いゾーンで、主にオールインかフォールドしか残りません。","green-zone":"Mが高いゾーンで、スタックに余裕があり、自由に、慎重にも積極的にもプレイできます。","ante":"配る前に全プレイヤーがポットに入れる、少額の強制的な支払いです（主にトーナメント）。","bb-ante":"全プレイヤーの代わりに、ビッグブラインドのプレイヤーがテーブル全体のアンティを払う形式です。","fold-equity":"相手がフォールドする可能性から生まれる、プレイの価値の一部です。","gap-concept":"オープンにコールするには、自分でオープンするより強い手が必要だという原則です。","chip-ev":"お金に換算せずに（ICMなしで）チップで計算した、プレイの期待値です。","tournament-equity":"その賞金構造とスタックのもとで期待できる、プライズプールの自分の取り分です。「$EV」とも呼ばれます。","prize-pool":"トーナメントで賞金を得るプレイヤーの間で分けられるお金の合計です。","payout":"トーナメントの特定の順位に対する賞金です。すべて合わせて賞金の配分になります。","pay-jump":"トーナメントで隣り合う順位の間の賞金の差です。差が大きいほどリスクプレミアムが大きくなります。","final-table":"トーナメントの最後のテーブルで、最も高い賞金を争います。","short-stack":"ブラインドに比べて小さいスタックです。トーナメントでは通常、ビッグブラインドがわずかしか残っていない状態を指します。","nash-equilibrium":"どのプレイヤーも自分の戦略だけを変えても得をしない、戦略の組み合わせです。","overcall":"前のプレイヤーがすでにコールしたベットにコールすることです。","heads-up":"1対1のプレイで、テーブルまたはハンドに2人のプレイヤーだけが残った状態です。","dead-money":"もうポットを獲得できないプレイヤーがポットに入れたチップです。例：フォールドしたプレイヤーのチップ。","stack-off":"1つのハンドでスタックをすべてポットに入れること、つまりオールインするか、オールインにコールすることです。","exploit":"相手、またはプレイヤー層全体の特定のミスを突くために、基本の戦略から意図的に外れることです。","hud":"オンラインプレイでテーブルに重ねて表示され、以前にプレイしたハンドから相手の統計を示すツールです。","vpip":"HUDの統計で、フロップ前にプレイヤーが自分の意思でポットにお金を入れる（コールまたはレイズする）ハンドの割合です。","pfr":"HUDの統計で、プレイヤーがフロップ前にレイズするハンドの割合です。","wtsd":"HUDの統計で、フロップを見たプレイヤーがショーダウンまで行く頻度です。","nit":"とてもタイトなプレイヤーで、ほぼ強い手だけでポットに参加します。","regular":"そのステークスに常にいて、多くのハンドをプレイするプレイヤーです。このコースではレクリエーショナルプレイヤーと対比します。","tag":"タイトアグレッシブなスタイルで、プレイする手は少ないものの、積極的に（ベットやレイズで）プレイします。","lag":"ルースアグレッシブなスタイルで、多くの手を積極的にプレイします。","recreational":"楽しみのためにプレイし、通常はレギュラーより弱いプレイヤーです。俗語では見下して「フィッシュ」と呼ばれます。","calling-station":"弱い手やドローでも、とても頻繁にコールするプレイヤーを見下した呼び方です。","maniac":"何でもベットやレイズする、とてもルースでアグレッシブなプレイヤーを見下した呼び方です。","rake":"カジノやオンラインのポーカールームが、ゲーム運営の対価としてポットから取る手数料です。","rake-cap":"ポーカールームが1つのハンドから取れるレーキの上限額です。"},
  "pt-BR": {"royal-flush":"A mão mais alta do pôquer: ás, rei, dama, valete e dez do mesmo naipe, por exemplo, A♠ K♠ Q♠ J♠ T♠.","straight-flush":"Cinco cartas em sequência do mesmo naipe, por exemplo, 5♥ 6♥ 7♥ 8♥ 9♥. A versão mais alta (do ás ao dez) tem nome próprio e é a mão mais forte do jogo.","four-of-a-kind":"Quatro cartas do mesmo valor, por exemplo, quatro setes. Entre duas quadras do mesmo valor, vence a quinta carta mais alta (o kicker).","full-house":"Uma trinca e um par na mesma mão, por exemplo, três damas e dois cincos. Entre dois full houses, vence a trinca mais alta.","flush":"Cinco cartas do mesmo naipe (♠, ♥, ♦ ou ♣) que não estão em sequência. Entre duas mãos assim, vence a que tem a carta mais alta; se elas forem iguais, decide a carta seguinte.","straight":"Cinco cartas em sequência, nem todas do mesmo naipe, por exemplo, 5-6-7-8-9. O ás pode ser a carta mais alta (A-K-Q-J-T) ou a mais baixa (A-2-3-4-5).","three-of-a-kind":"Três cartas do mesmo valor e duas outras. No hold'em, há duas variantes com nomes próprios: set, quando o par está na sua mão e a terceira carta no board, e trips, quando o par está no board e a terceira carta na sua mão.","set":"Trinca formada por um par na sua mão e uma carta do board, por exemplo, 7♣ 7♦ num flop K-7-2.","two-pair":"Dois pares diferentes e uma quinta carta, por exemplo, K-K-8-8-3. O empate é decidido primeiro pelo par mais alto, depois pelo mais baixo e, por fim, pela quinta carta.","pair":"Duas cartas do mesmo valor e três outras, por exemplo, dois noves. Só a carta alta é mais fraca.","high-card":"Mão sem par nem combinação melhor; a força é definida pela carta mais alta e, em caso de empate, pelas seguintes.","kicker":"A carta mais alta fora da combinação, que desempata. Exemplo: um par de ases com rei vence um par de ases com dama.","wheel":"A sequência mais baixa: A-2-3-4-5, em que o ás conta como a carta mais baixa.","check":"Continuar sem colocar fichas, possível só quando você não precisa pagar nada: ninguém apostou ainda nesta rodada de apostas (antes do flop, o big blind pode fazer isso quando ninguém deu raise). Não confunda com call, que é colocar fichas para igualar a aposta do adversário.","bet":"As primeiras fichas colocadas numa rodada de apostas em que ninguém apostou ainda (em sentido mais amplo, chama-se aposta qualquer colocação de fichas no pote).","call":"Colocar no pote o valor da aposta ou do raise do adversário para continuar jogando. Não confunda com check, que é continuar sem apostar quando ninguém apostou.","raise":"Aumentar o valor acima da aposta do adversário; os outros jogadores precisam completar a diferença, dar outro raise ou dar fold.","fold":"Desistir da mão: você descarta as cartas e perde o que já colocou no pote.","check-raise":"Primeiro você dá check e, quando o adversário aposta, dá raise na mesma rodada de apostas.","all-in":"Apostar todas as suas fichas. Assim, de cada adversário você pode ganhar no máximo o que você mesmo colocou; o restante é disputado num pote paralelo.","pot":"Todas as fichas apostadas na mão atual. Elas vão para o jogador com a melhor mão no showdown (com potes paralelos, cada pote é decidido separadamente) ou para o jogador que sobra quando todos os outros dão fold.","side-pot":"Pote separado criado quando alguém está all-in: só disputam esse pote os jogadores que colocaram mais que o jogador all-in, por isso ele não pode ganhá-lo.","split-pot":"Situação em que jogadores com mãos iguais dividem o pote, por exemplo, quando ambos jogam a mesma sequência que está no board.","playing-the-board":"Situação em que sua melhor mão de cinco cartas é formada só pelas cartas comunitárias; suas cartas fechadas não acrescentam nada, então, na melhor das hipóteses, você divide o pote.","board":"As cartas comunitárias abertas no centro (flop, turn, river), usadas por todos os jogadores. O termo se refere às cartas, não à mesa onde se joga.","community-cards":"Cartas colocadas abertas no centro, que qualquer jogador pode usar para formar sua mão; no hold'em são cinco.","hole-cards":"As duas cartas fechadas que você recebe no início da mão no hold'em; só você as vê.","small-blind":"A aposta obrigatória menor, feita antes da distribuição pelo jogador à esquerda do button (no heads-up, pelo próprio button); esse lugar na mesa também tem esse nome.","big-blind":"A aposta obrigatória maior, feita antes da distribuição pelo segundo jogador à esquerda do button (no heads-up, pelo jogador oposto ao button); esse lugar também tem esse nome. Também serve de unidade para o tamanho dos stacks e para os resultados.","chips":"Os discos usados para jogar na mesa; nos cash games representam dinheiro e, nos torneios, pontos do torneio.","stack":"Todas as fichas que um jogador tem à sua frente; geralmente indicado em big blinds (por exemplo, 100 big blinds).","street":"Nome informal de uma rodada de apostas: preflop, flop, turn e river são as quatro streets. Exemplo: “value em três streets” significa apostas de valor no flop, no turn e no river.","betting-round":"Etapa da mão em que os jogadores, cada um na sua vez, dão check, apostam, dão call, dão raise ou dão fold; no hold'em são quatro: preflop, flop, turn e river.","preflop":"A primeira rodada de apostas: depois que as cartas fechadas são distribuídas e antes de o flop ir para a mesa.","flop":"As três primeiras cartas comunitárias, abertas juntas após as apostas do preflop; a segunda rodada de apostas também tem esse nome.","turn":"A quarta carta comunitária e a terceira rodada de apostas.","river":"A quinta e última carta comunitária e a última rodada de apostas antes do showdown.","showdown":"A revelação das cartas depois da última rodada de apostas, quando pelo menos dois jogadores continuam na mão; a melhor mão leva o pote.","position":"Seu lugar na mesa em relação ao button, que define a ordem de ação. Quem age depois vê mais ações dos adversários antes de decidir.","in-position":"Situação do jogador que age por último depois do flop e, por isso, vê a ação do adversário antes de decidir.","out-of-position":"Situação do jogador que age antes do adversário depois do flop e, por isso, decide sem conhecer a ação dele.","early-position":"Os primeiros lugares a agir antes do flop (por exemplo, UTG); ainda há muitos jogadores para agir depois de você.","late-position":"Os lugares que agem por último: o button e os lugares logo antes dele, principalmente o cutoff.","utg":"O primeiro jogador a agir antes do flop, sentado imediatamente à esquerda do big blind.","hijack":"O lugar imediatamente antes do cutoff, ou seja, o segundo à direita do button.","cutoff":"O lugar imediatamente à direita do button, que age logo antes dele.","button":"O lugar do dealer, marcado com um disco “dealer”. Depois do flop, age por último em todas as rodadas de apostas.","outs":"Carta que ainda está no baralho e vai melhorar sua mão, geralmente completando um draw. Exemplo: com um flush draw, seus outs são as cartas restantes do seu naipe.","draw":"Mão que ainda não é forte, mas pode se tornar forte com as próximas cartas comunitárias, por exemplo, quando falta uma carta para um flush ou uma sequência.","flush-draw":"Quatro cartas do mesmo naipe (somando a mão e o board); falta uma para completar o flush.","straight-draw":"Quatro cartas às quais falta uma para formar uma sequência. Tipos: OESD (falta uma carta em uma das duas pontas) e gutshot (falta uma carta no meio).","oesd":"Sigla de open-ended straight draw: straight draw de quatro cartas em sequência, completado por uma carta em qualquer das duas pontas, por exemplo, 5-6-7-8 espera um quatro ou um nove.","gutshot":"Straight draw ao qual falta um valor específico no meio, por exemplo, 5-6-8-9 espera só um sete.","backdoor":"Draw no flop que precisa de duas cartas favoráveis seguidas, no turn e no river, por exemplo, três cartas do mesmo naipe depois do flop.","pot-odds":"A relação entre o valor que você precisa colocar e o pote que pode ganhar (incluindo a aposta do adversário). Mostra com que frequência você precisa ganhar para que o call valha a pena.","implied-odds":"Pot odds acrescidas das fichas que você espera ganhar nas streets seguintes se acertar sua mão.","equity":"Sua chance de ganhar o pote se todas as cartas restantes fossem abertas sem mais apostas; geralmente em porcentagem.","equity-realization":"Quanto da sua equity uma mão transforma em ganho quando as apostas continuam (pode realizar menos ou mais do que sua equity); depende, entre outras coisas, da posição e da facilidade de jogar a mão.","expected-value":"O resultado médio de uma jogada se ela fosse repetida muitas vezes. Uma jogada positiva na média dá lucro no longo prazo, mesmo que perca desta vez.","combo":"Uma combinação específica de duas cartas com naipes, por exemplo, A♠ K♥. Contar essas combinações mostra quantas mãos de um tipo há de fato num range.","range":"O conjunto de todas as mãos que um jogador pode ter numa situação, ou das mãos com as quais ele faria determinada jogada.","mixed-hand":"Mão com a qual a estratégia de equilíbrio escolhe ora uma jogada, ora outra (por exemplo, às vezes raise, às vezes call); as duas jogadas são corretas. Também se diz que essa mão é jogada com estratégia mista.","open":"Entrar no pote antes do flop com um raise quando todos antes de você deram fold.","suited":"Duas cartas fechadas do mesmo naipe, por exemplo, A♥ K♥ (notação AKs).","offsuit":"Duas cartas fechadas de naipes diferentes, por exemplo, A♥ K♣ (notação AKo).","pocket-pair":"Par formado pelas duas cartas fechadas, por exemplo, 8♣ 8♦ antes do flop.","connectors":"Cartas fechadas de valores vizinhos, por exemplo, 8-7 ou 9-8; com elas é mais fácil formar uma sequência.","3-bet":"O primeiro raise sobre um open antes do flop; o nome conta o big blind como a primeira aposta e o open como a segunda.","4-bet":"Um raise sobre um 3-bet, ou seja, a quarta aposta na rodada de apostas.","limp":"Entrar no pote antes do flop apenas pagando o big blind, quando ninguém deu raise ainda.","isolation":"Raise depois de um ou mais limps, para jogar contra o limper (muitas vezes um jogador mais fraco) no mano a mano.","texture":"As características das cartas comunitárias: quantos naipes há, se as cartas são próximas entre si, se há um par. Isso define quais mãos e draws são possíveis.","dry":"Board em que poucos draws e mãos fortes são possíveis, por exemplo, K♠ 7♦ 2♣.","wet":"Board em que muitos draws e mãos fortes são possíveis, por exemplo, J♥ T♥ 8♣.","rainbow":"Flop com três cartas de três naipes diferentes, então ninguém tem flush draw no flop.","two-tone":"Flop com duas cartas do mesmo naipe, então flush draws são possíveis.","monotone":"Flop com três cartas do mesmo naipe, então um flush pode já estar formado.","paired":"Board com um par (duas cartas do mesmo valor), por exemplo, 8-8-3.","connected":"Board em que alguém pode já ter formado uma sequência, por exemplo, 9-8-7.","disconnected":"Board com cartas distantes entre si, em que é difícil formar uma sequência ou um straight draw, por exemplo, K-7-2.","semi-connected":"Board com straight draws possíveis, mas ainda sem sequência possível, por exemplo, T-8-3 (classificação adotada neste curso).","wetness":"O quanto um board favorece draws e mãos fortes: de seco a molhado. Também se descreve como o grau de coordenação do board.","top-pair":"Par com a carta mais alta do board, por exemplo, K♠ Q♦ num flop K-7-2.","second-pair":"Par com a segunda carta mais alta do board, por exemplo, 7♠ 6♠ num flop K-7-2.","overpair":"Pocket pair mais alto que todas as cartas do board, por exemplo, Q-Q num flop J-7-2.","c-bet":"Aposta de continuação: aposta do jogador que foi o agressor na rodada anterior, por exemplo, uma aposta no flop depois de dar open no preflop.","aggressor":"O jogador que apostou ou deu raise por último na rodada de apostas anterior.","initiative":"O papel do último agressor: geralmente é ele quem faz a próxima aposta.","range-advantage":"Situação em que o range de um jogador tem, no total, mais equity num determinado board do que o range do adversário.","nuts-advantage":"Situação em que um jogador tem no range, proporcionalmente, mais das mãos mais fortes do que o adversário.","nuts":"A mão mais forte possível num determinado board naquele momento. Exemplo: no board K♥ 9♥ 4♥ 2♣, é o flush com o ás de copas.","polarized":"Sobre um range: formado principalmente por mãos muito fortes e por blefes, quase sem mãos médias.","polarization":"Montar um range com os extremos: mãos fortes para valor e blefes, sem mãos médias.","linear":"Sobre um range: montado de cima para baixo, das mãos mais fortes em diante, sem um grupo separado de blefes. Você também verá o termo relacionado “merged range” (range não polarizado); segundo análises de solver publicadas, o merged é um formato intermediário entre este range e o polarizado.","condensed":"Sobre um range: sem as mãos mais fortes (limitado por cima) e formado principalmente por mãos médias; o oposto do polarizado.","value":"Apostar com uma mão forte para que o adversário pague com uma mão mais fraca.","value-bet":"Uma aposta única por valor: feita com uma mão forte para que mãos mais fracas paguem.","bluff":"Aposta com uma mão fraca, que dificilmente vence no showdown, para que o adversário dê fold com uma mão melhor.","semi-bluff":"Aposta com uma mão ainda fraca, mas com chance de melhorar (por exemplo, com um draw): você ganha se o adversário der fold ou se acertar.","blocker":"Carta na sua mão que reduz a chance de o adversário ter certas mãos. Exemplo: com o ás de copas, o adversário não pode ter o flush de copas com ás.","bluff-catcher":"Mão que vence apenas os blefes do adversário e perde para as apostas de valor dele.","barrel":"Mais uma aposta na rodada de apostas seguinte, depois da sua própria aposta na rodada anterior.","second-barrel":"Segunda aposta seguida: depois de um c-bet no flop, o jogador aposta de novo no turn.","probe-bet":"Aposta no turn do jogador fora de posição depois que o agressor do preflop deu check no flop em vez de fazer c-bet.","donk-bet":"Aposta de um jogador que aposta antes de o agressor da rodada anterior ter tido a chance de agir.","overbet":"Aposta depois do flop maior que o pote inteiro.","effective-stack":"Numa mão entre dois jogadores: o menor dos dois stacks, ou seja, o máximo que se pode realmente ganhar ou perder. Com vários jogadores, é calculado separadamente para cada par.","spr":"O stack efetivo dividido pelo pote no início de uma street (para planejar a mão, é calculado no flop); mostra quão profundos são os stacks em relação ao pote (quanto menor o SPR, mais rápido tudo vai para o pote).","mdf":"A menor parte do range que você precisa defender contra uma aposta para que o blefe do adversário com uma mão sem chances não seja automaticamente lucrativo.","alpha":"Com que frequência o adversário precisa dar fold para que um blefe com uma mão sem chances fique no zero a zero; depende do tamanho da aposta em relação ao pote.","variance":"A dispersão dos resultados em torno do valor esperado: mesmo jogando bem, sequências curtas podem ter grandes perdas ou grandes ganhos.","buy-in":"O valor de entrada num torneio ou para sentar num cash game.","bankroll":"Toda a reserva destinada exclusivamente a jogar pôquer; neste app, é contada em buy-ins, não em dinheiro.","tilt":"Estado em que as emoções (raiva, frustração, euforia) pioram suas decisões na mesa.","winrate":"O resultado médio de um jogador numa amostra maior; nos cash games, geralmente em bb/100, ou seja, big blinds por cem mãos.","downswing":"Período de resultados claramente piores, geralmente perdas maiores do que a habilidade justificaria; o oposto de um upswing.","session":"Uma sentada de pôquer, do início ao fim do jogo.","stakes":"O valor dos blinds num cash game ou do buy-in num torneio; “microlimites” são os níveis mais baixos.","standard-deviation":"Medida da dispersão dos resultados (a raiz quadrada da variância); no pôquer, geralmente em bb/100.","risk-of-ruin":"A probabilidade de você um dia perder todo o seu bankroll se continuar jogando no mesmo limite.","mental-game":"O lado psicológico do pôquer: lidar com o tilt, as emoções e a concentração na mesa.","tournament":"Formato em que os blinds sobem de tempos em tempos e o jogo continua até um jogador ficar com todas as fichas; os prêmios vão para os mais bem colocados.","push-fold":"Estratégia simplificada para short stacks: antes do flop, você ou vai all-in, ou dá fold.","shove":"Jogada all-in, geralmente como raise antes do flop.","icm":"Modelo que converte fichas de torneio em valor em dinheiro, considerando a estrutura de premiação e os stacks de todos os jogadores.","bubble":"Fase do torneio logo antes das posições premiadas, quando ainda faltam algumas eliminações para chegar aos prêmios.","bubble-factor":"Indicador do ICM: quanto, num torneio, perder uma certa quantidade de fichas dói mais do que ganhar a mesma quantidade ajuda.","cover":"Ter pelo menos tantas fichas quanto o adversário. Quando um adversário cobre você, perder um all-in contra ele encerra seu torneio.","risk-premium":"Equity extra, além do que as pot odds exigem, necessária num torneio para arriscar um all-in, porque perder custa mais do que ganhar rende.","m-ratio":"Seu stack dividido pela soma dos blinds e antes de uma mão: quantas voltas completas (órbitas) suas fichas aguentam sem jogar.","red-zone":"Zona de M muito baixo: sobra principalmente ir all-in ou dar fold.","green-zone":"Zona de M alto: o stack permite jogar livremente, de forma conservadora ou agressiva.","ante":"Pequena contribuição obrigatória ao pote antes da distribuição, feita por todos os jogadores (principalmente em torneios).","bb-ante":"Formato de ante em que, em vez de todos os jogadores, o jogador no big blind paga o ante da mesa inteira.","fold-equity":"A parte do valor de uma jogada que vem da possibilidade de o adversário dar fold.","gap-concept":"O princípio de que é preciso uma mão mais forte para pagar um open do que para dar open.","chip-ev":"O valor esperado de uma jogada calculado em fichas, sem convertê-las em dinheiro (sem ICM).","tournament-equity":"Sua parte esperada da premiação total, dadas a estrutura de premiação e os stacks. Também é chamada de “$EV”.","prize-pool":"O total de dinheiro a ser dividido entre os jogadores premiados de um torneio.","payout":"O prêmio por uma colocação específica no torneio; juntos, eles formam a distribuição dos prêmios.","pay-jump":"A diferença de prêmio entre colocações vizinhas num torneio; saltos grandes aumentam o risk premium.","final-table":"A última mesa de um torneio, onde se disputam os maiores prêmios.","short-stack":"Stack pequeno em relação aos blinds; nos torneios, geralmente um com poucos big blinds restantes.","nash-equilibrium":"Conjunto de estratégias em que nenhum jogador ganha nada mudando apenas a própria estratégia.","overcall":"Pagar uma aposta que alguém antes de você já pagou.","heads-up":"Jogo mano a mano: só restam dois jogadores na mesa ou na mão.","dead-money":"Fichas no pote de jogadores que já não podem ganhá-lo, por exemplo, dos que deram fold.","stack-off":"Colocar o stack inteiro no pote numa única mão, ou seja, ir all-in ou pagar um all-in.","exploit":"Desvio deliberado da estratégia base para aproveitar um erro específico de um adversário ou de toda a população de jogadores.","hud":"Sobreposição na mesa do jogo online que mostra estatísticas dos adversários a partir de mãos jogadas anteriormente.","vpip":"Estatística do HUD: em que porcentagem das mãos o jogador coloca dinheiro voluntariamente no pote antes do flop (dá call ou raise).","pfr":"Estatística do HUD: em que porcentagem das mãos o jogador dá raise antes do flop.","wtsd":"Estatística do HUD: com que frequência um jogador que viu o flop chega ao showdown.","nit":"Jogador muito tight, que entra no pote quase só com mãos fortes.","regular":"Jogador frequente num determinado limite, que joga um grande volume de mãos; no curso, é contraposto ao jogador recreativo.","tag":"Estilo tight agressivo: poucas mãos, mas jogadas de forma agressiva (apostas e raises).","lag":"Estilo loose agressivo: muitas mãos, jogadas de forma agressiva.","recreational":"Jogador que joga por diversão e geralmente é mais fraco que os regs; no jargão, de forma pejorativa, “fish”.","calling-station":"Termo pejorativo para um jogador que paga com muita frequência, mesmo com mãos fracas ou draws.","maniac":"Termo pejorativo para um jogador muito loose e agressivo, que aposta e dá raise com qualquer coisa.","rake":"A taxa que o cassino ou a sala online cobra do pote para organizar o jogo.","rake-cap":"O valor máximo de rake que a sala pode cobrar de uma única mão."},
  "zh-Hant": {"royal-flush":"撲克中最大的牌型：同一花色的 A、K、Q、J、10，例如 A♠ K♠ Q♠ J♠ T♠。","straight-flush":"同一花色的五張連續牌，例如 5♥ 6♥ 7♥ 8♥ 9♥。其中最大的一種（A 到 10）有自己的名稱，是遊戲中最強的牌型。","four-of-a-kind":"四張點數相同的牌，例如四張 7。若兩手四條點數相同，第五張牌（踢腳）較大者獲勝。","full-house":"同一手牌中有三條加一對，例如三張 Q 和兩張 5。兩手葫蘆相比時，三條較大者獲勝。","flush":"五張同花色（♠、♥、♦ 或 ♣）但不連續的牌。兩手同花相比時，最大的牌較大者獲勝；若相同，則比下一張。","straight":"五張連續的牌，但不全是同一花色，例如 5-6-7-8-9。A 可以當最大的牌（A-K-Q-J-T），也可以當最小的牌（A-2-3-4-5）。","three-of-a-kind":"三張點數相同的牌加另外兩張牌。在德州撲克中分成兩種，各有名稱：暗三條（對子在手上，第三張在牌面上）和明三條（對子在牌面上，第三張在手上）。","set":"由手上的一對加牌面上一張牌組成的三條，例如在 K-7-2 的翻牌拿著 7♣ 7♦。","two-pair":"兩個不同的對子加第五張牌，例如 K-K-8-8-3。平手時先比較大的對子，再比較小的對子，最後比第五張牌。","pair":"兩張點數相同的牌加另外三張牌，例如兩張 9。只有高牌比它弱。","high-card":"沒有對子或更好組合的牌；強弱由最大的牌決定，平手時再依序比下一張。","kicker":"牌型以外最大的一張牌，用來分出平手。例如：一對 A 帶 K，贏一對 A 帶 Q。","wheel":"最小的順子：A-2-3-4-5，其中 A 當作最小的牌。","check":"不投入籌碼繼續玩，只有在你不需要補任何籌碼時才能這麼做：這個下注輪還沒有人下注（翻牌前，若沒人加注，大盲可以過牌）。不要和跟注搞混：跟注是補上對手的下注。","bet":"在還沒有人下注的下注輪中第一個投入籌碼（廣義來說，任何投入底池的籌碼都可以叫下注）。","call":"投入與對手下注或加注相同的金額到底池，以便繼續玩。不要和過牌搞混：過牌是在沒人下注時不下注繼續玩。","raise":"把金額提高到對手的下注之上；其他玩家必須補上差額、再加注或棄牌。中文也稱「加碼」。","fold":"放棄這手牌：你交出手牌，並失去已經投入底池的籌碼。","check-raise":"你先過牌，等對手下注後，在同一個下注輪中對他加注。","all-in":"投入你所有的籌碼。這時你從每位對手身上最多只能贏到你自己投入的數量；其餘部分在邊池中另行爭奪。","pot":"目前這手牌中所有下注的籌碼。由攤牌時牌型最好的玩家拿走（有邊池時每個底池分開決定），或由其他人都棄牌後剩下的玩家拿走。","side-pot":"有人全下時形成的另一個底池：只有投入比全下玩家更多的玩家能爭奪它，所以全下玩家本人無法贏得它。","split-pot":"牌型相同的玩家平分底池的情況，例如雙方都用牌面上的同一個順子。","playing-the-board":"你最好的五張牌型完全由公共牌組成的情況；你的底牌沒有任何幫助，所以最好的結果是平分底池。","board":"中間翻開的公共牌（翻牌、轉牌、河牌），所有玩家都可以使用。這裡指的是牌，不是你坐的牌桌。","community-cards":"翻開放在中間、每位玩家都能用來組成牌型的牌；德州撲克中共有五張。","hole-cards":"德州撲克中每手牌開始時你拿到的兩張蓋著的牌；只有你看得到。","small-blind":"發牌前由按鈕位左邊玩家投入的較小強制下注（兩人對局時由按鈕位本人投入）；這個座位也叫這個名稱。","big-blind":"發牌前由按鈕位左邊第二位玩家投入的較大強制下注（兩人對局時由按鈕位對面的玩家投入）；這個座位也叫這個名稱。它也被當作籌碼量和成績的單位。","chips":"在牌桌上用來玩牌的圓片；現金桌中代表金錢，錦標賽中代表比賽積分。","stack":"玩家面前所有的籌碼；通常以大盲數表示（例如 100 個大盲）。","street":"下注輪的行話稱呼：翻牌前、翻牌、轉牌和河牌是四條街。例如：「三條街拿價值」指在翻牌、轉牌和河牌都做價值下注。","betting-round":"一手牌中玩家輪流過牌、下注、跟注、加注或棄牌的階段；德州撲克有四個：翻牌前、翻牌、轉牌和河牌。","preflop":"第一個下注輪：發完底牌之後，翻牌出現之前。","flop":"翻牌前下注結束後一次發出的前三張公共牌；第二個下注輪也叫這個名稱。","turn":"第四張公共牌，也是第三個下注輪。","river":"第五張、也是最後一張公共牌，以及攤牌前的最後一個下注輪。","showdown":"最後一輪下注後，至少還有兩位玩家在局中時亮出手牌；牌型最好的人拿走底池。","position":"你在牌桌上相對於按鈕位的座位，決定行動順序。越晚行動的人，在做決定前能看到越多對手的動作。","in-position":"翻牌後最後行動的玩家所處的情況，所以他在決定前能看到對手的動作。","out-of-position":"翻牌後比對手先行動的玩家所處的情況，所以他必須在不知道對手動作的情況下做決定。","early-position":"翻牌前最先行動的座位（例如槍口位）；你後面還有很多玩家要行動。","late-position":"最後行動的座位：按鈕位以及緊鄰它之前的座位，尤其是關煞位。","utg":"翻牌前第一個行動的玩家，坐在大盲的正左邊。","hijack":"緊鄰關煞位之前的座位，也就是按鈕位右邊第二個座位。","cutoff":"按鈕位正右邊的座位，緊接在按鈕位之前行動。","button":"發牌者的座位，用寫著「dealer」的圓片標示。翻牌後，它在每個下注輪都最後行動。","outs":"還在牌堆中、能改進你手牌的牌，通常是能完成聽牌的牌。例如：同花聽牌時，你的補牌就是剩下的同花色牌。","draw":"還不是強牌型、但之後的公共牌可能讓它變成強牌型的手牌，例如還差一張就成同花或順子。","flush-draw":"四張同花色的牌（手牌和牌面合計）；再一張就成同花。","straight-draw":"還差一張就成順子的四張牌。種類：兩頭順（缺的牌在兩端任一端）和卡順（缺的牌在中間）。","oesd":"兩頭順，英文 open-ended straight draw（縮寫 OESD）：由四張連續牌組成的順子聽牌，兩端的牌都能完成，例如 5-6-7-8 等 4 或 9。","gutshot":"中間缺一個特定點數的順子聽牌，例如 5-6-8-9 只等 7。","backdoor":"翻牌時需要轉牌和河牌連續兩張都中的聽牌，例如翻牌後有三張同花色的牌。","pot-odds":"你需要投入的金額與你可以贏得的底池（包含對手的下注）之間的比例。它告訴你需要多常贏，跟注才有利可圖。","implied-odds":"底池賠率加上你成牌後預期在後面幾條街能贏到的籌碼。","equity":"如果剩下的牌全部發完、不再下注，你贏得底池的機率；通常以百分比表示。","equity-realization":"下注繼續進行時，一手牌能把多少權益轉成實際贏得的籌碼（可能少於或多於它的權益）；取決於位置以及這手牌好不好打等因素。","expected-value":"某個打法重複很多次後的平均結果。平均為正的打法長期會賺錢，即使這一次輸了。","combo":"一種特定、含花色的兩張牌組合，例如 A♠ K♥。計算這些組合可以看出某種手牌在範圍中實際有多少種。","range":"玩家在某個情況下可能持有的所有手牌，或他會用來採取某個打法的手牌。","mixed-hand":"均衡策略有時選一種打法、有時選另一種打法的手牌（例如有時加注、有時跟注）；兩種打法都正確。也可以說這手牌是用混合策略來打。","open":"前面的人都棄牌時，你在翻牌前以加注第一個進入底池。","suited":"兩張底牌同一花色，例如 A♥ K♥（寫作 AKs）。","offsuit":"兩張底牌花色不同，例如 A♥ K♣（寫作 AKo）。","pocket-pair":"由兩張底牌組成的對子，例如翻牌前的 8♣ 8♦。","connectors":"點數相鄰的底牌，例如 8-7 或 9-8；比較容易組成順子。","3-bet":"翻牌前對開池的第一次加注；這個名稱把大盲算作第一注，開池算作第二注。","4-bet":"對 3-bet 的加注，也就是一個下注輪中的第四注。","limp":"還沒有人加注時，翻牌前只跟注大盲進入底池。","isolation":"在一個或多個溜入之後加注，目的是和溜入者（通常是較弱的玩家）單挑。","texture":"公共牌的特性：有幾種花色、牌之間是否接近、是否有對子。它決定了哪些牌型和聽牌是可能的。","dry":"可能的聽牌和強牌型很少的牌面，例如 K♠ 7♦ 2♣。","wet":"可能的聽牌和強牌型很多的牌面，例如 J♥ T♥ 8♣。","rainbow":"三張牌分屬三種不同花色的翻牌，所以翻牌時沒有人有同花聽牌。","two-tone":"有兩張牌同花色的翻牌，所以可能有同花聽牌。","monotone":"三張牌都同花色的翻牌，所以可能已經有人成同花。","paired":"有對子（兩張點數相同的牌）的牌面，例如 8-8-3。","connected":"可能已經有人組成順子的牌面，例如 9-8-7。","disconnected":"牌與牌距離很遠、很難組成順子或順子聽牌的牌面，例如 K-7-2。","semi-connected":"有順子聽牌、但還不可能組成順子的牌面，例如 T-8-3（本課程採用的分類）。","wetness":"牌面有利於聽牌和強牌型的程度：從乾燥到濕潤。也可以用牌面的協調程度來描述。","top-pair":"用牌面上最大的牌組成的對子，例如在 K-7-2 的翻牌拿著 K♠ Q♦。","second-pair":"用牌面上第二大的牌組成的對子，例如在 K-7-2 的翻牌拿著 7♠ 6♠。","overpair":"比牌面上每一張牌都大的口袋對，例如在 J-7-2 的翻牌拿著 Q-Q。","c-bet":"持續下注：上一輪身為進攻者的玩家所做的下注，例如翻牌前開池後在翻牌下注。","aggressor":"在上一個下注輪中最後下注或加注的玩家。","initiative":"最後進攻者的角色：通常由他做下一次下注。","range-advantage":"在某個牌面上，一位玩家的範圍整體權益高於對手範圍的情況。","nuts-advantage":"一位玩家範圍中最強手牌的比例高於對手的情況。","nuts":"在某個牌面、某個時刻可能的最強手牌。例如：牌面 K♥ 9♥ 4♥ 2♣ 時，堅果牌是帶紅心 A 的同花。","polarized":"形容範圍：主要由非常強的牌和詐唬組成，幾乎沒有中等牌。","polarization":"用兩個極端建構範圍：拿價值的強牌和詐唬，沒有中等牌。","linear":"形容範圍：從最強的牌往下建構，沒有單獨的一組詐唬。你也會看到相關的說法「merged range」（非極化範圍）；根據已發表的求解器分析，merged 是介於這種範圍和極化範圍之間的形態。","condensed":"形容範圍：沒有最強的牌（上限受限），主要由中等牌組成；與極化相反。","value":"用強牌下注，讓對手用較弱的牌跟注。","value-bet":"單次的價值下注：用強牌下注，讓較弱的牌跟注。","bluff":"用在攤牌時不太可能贏的弱牌下注，讓對手棄掉更好的牌。","semi-bluff":"用目前仍弱、但有機會改進的牌下注（例如聽牌）：對手棄牌或你中牌，你都能贏。","blocker":"你手上的一張牌，能降低對手持有某些手牌的機率。例如：你拿著紅心 A，對手就不可能有帶紅心 A 的同花。","bluff-catcher":"只能贏對手的詐唬、會輸給他價值下注的手牌。","barrel":"在上一輪自己下注之後，下一個下注輪再次下注。","second-barrel":"連續第二次下注：在翻牌持續下注後，玩家在轉牌再次下注。","probe-bet":"翻牌前進攻者在翻牌過牌、沒有持續下注後，無位置玩家在轉牌的下注。","donk-bet":"在上一輪的進攻者還沒來得及行動前，就先下注的玩家所做的下注。","overbet":"翻牌後大於整個底池的下注。","effective-stack":"兩位玩家的牌局中：兩人籌碼量中較小的那一個，也就是實際上最多能贏或輸的數量。多位玩家時，每兩人分別計算。","spr":"有效籌碼量除以某條街開始時的底池（規劃整手牌時以翻牌來計算）；表示籌碼量相對於底池有多深（SPR 越低，所有籌碼越快進入底池）。","mdf":"面對下注時必須防守的最小範圍比例，讓對手用毫無勝算的牌詐唬時不會自動獲利。","alpha":"對手要多常棄牌，用毫無勝算的牌詐唬才能打平；取決於下注大小相對於底池的比例。","variance":"結果圍繞期望值的波動程度：即使打得好，短期內也可能大輸或大贏。","buy-in":"參加錦標賽或在現金桌入座的金額。","bankroll":"專門留給打撲克的全部資金；在這個 App 中以買入數計算，而不是金額。","tilt":"情緒（憤怒、挫折、狂喜）讓你在牌桌上的決定變差的狀態。","winrate":"玩家在較長樣本中的平均成績；現金桌通常以 bb/100 表示，也就是每一百手牌贏多少大盲。","downswing":"成績明顯變差的時期，通常虧損比實力應有的更大；與上風期相反。","session":"一次打撲克，從開始玩到停止。","stakes":"現金桌的盲注大小或錦標賽的買入金額；「微級別」是最低的級別。","standard-deviation":"衡量結果波動的指標（變異的平方根）；撲克中通常以 bb/100 表示。","risk-of-ruin":"如果你繼續在同一級別打下去，最終輸光全部資金的機率。","mental-game":"撲克的心理層面：處理上頭、情緒和牌桌上的專注力。","tournament":"盲注每隔一段時間上升、一直打到一位玩家拿到所有籌碼為止的賽制；名次最高的玩家獲得獎金。","push-fold":"給短籌碼用的簡化策略：翻牌前只選擇全下或棄牌。","shove":"全下的打法，通常是翻牌前的加注。","icm":"把錦標賽籌碼換算成金錢價值的模型，考慮獎金結構和所有玩家的籌碼量。","bubble":"錦標賽中剛好在獎金圈之前的階段，還要再淘汰幾位玩家才有人進入獎金圈。","bubble-factor":"ICM 的指標：在錦標賽中，輸掉一定數量的籌碼帶來的傷害，比贏得同樣數量的籌碼帶來的好處大多少。","cover":"擁有至少和對手一樣多的籌碼。當對手覆蓋你時，全下輸給他就會讓你出局。","risk-premium":"在錦標賽中冒全下風險時，超出底池賠率要求所需的額外權益，因為輸的代價比贏的收益更大。","m-ratio":"你的籌碼量除以一手牌中盲注和前注的總和：不玩牌的話，你的籌碼能撐幾整圈。","red-zone":"M 值非常低的區域：主要只剩全下或棄牌。","green-zone":"M 值高的區域：籌碼量讓你可以自由地打，保守或積極都可以。","ante":"發牌前每位玩家投入底池的小額強制下注（主要在錦標賽）。","bb-ante":"一種前注形式：不是每位玩家都付，而是由大盲位玩家替全桌支付前注。","fold-equity":"打法價值中，來自對手可能棄牌的那一部分。","gap-concept":"原則：跟注別人的開池需要比自己開池更強的牌。","chip-ev":"以籌碼計算的打法期望值，不換算成金錢（不考慮 ICM）。","tournament-equity":"在既定獎金結構和籌碼量下，你預期能分到的獎池份額。也稱為「$EV」。","prize-pool":"錦標賽中要分給獲獎玩家的總金額。","payout":"錦標賽中某個名次的獎金；全部加起來構成獎金分配。","pay-jump":"錦標賽中相鄰名次之間的獎金差距；大的獎金跳躍會提高風險溢價。","final-table":"錦標賽的最後一桌，爭奪最高額的獎金。","short-stack":"相對於盲注很少的籌碼量；在錦標賽中通常指只剩不多大盲的籌碼量。","nash-equilibrium":"一組策略，在其中任何玩家只改變自己的策略都無法獲利。","overcall":"跟注一個前面已經有人跟注的下注。","heads-up":"一對一對戰：牌桌上或這手牌中只剩兩位玩家。","dead-money":"底池中來自已經不可能贏得它的玩家的籌碼，例如已棄牌的玩家。","stack-off":"在一手牌中把全部籌碼投入底池，也就是全下或跟注全下。","exploit":"刻意偏離基礎策略，以利用某位對手或整個玩家群體的特定錯誤。","hud":"線上遊戲中疊在牌桌上的介面，顯示對手在先前牌局中的統計數據。","vpip":"HUD 統計數據：玩家在翻牌前自願把錢投入底池（跟注或加注）的手牌比例。","pfr":"HUD 統計數據：玩家在翻牌前加注的手牌比例。","wtsd":"HUD 統計數據：看到翻牌的玩家走到攤牌的頻率。","nit":"非常緊的玩家，幾乎只用強牌進入底池。","regular":"某個級別的固定玩家，打很多手牌；本課程中與娛樂玩家相對。","tag":"緊兇風格：玩的牌少，但打得積極（下注和加注）。","lag":"鬆兇風格：玩的牌多，打得積極。","recreational":"為了娛樂而打牌的玩家，通常比常客弱；行話中貶稱為「魚」。","calling-station":"貶義說法，指非常常跟注的玩家，連弱牌或聽牌也跟。","maniac":"貶義說法，指非常鬆又兇、拿什麼牌都下注和加注的玩家。","rake":"賭場或線上撲克室為了經營牌局，從底池中抽取的費用。","rake-cap":"撲克室從單手牌中最多能抽取的抽水金額。"},
};

